def smartlead_create_campaign(client_id, name, settings=None, schedule=None, sequence_steps=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    clients = _load("clients.json")
    campaigns = _load("campaigns.json")

    def _mk_id(prefix):
        # vendor-like id: prefix + 18 chars from base32-ish alphabet (no I,L,O,U)
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = uuid.uuid4().int
        s = ""
        for _ in range(18):
            s = alphabet[raw % len(alphabet)] + s
            raw //= len(alphabet)
        return f"{prefix}{s}"

    def _record_audit(status_code, cred, extra=None):
        extra = extra or {}
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": _mk_id("sl_req_"),
            "endpoint": "smartlead_create_campaign",
            "credential_id": cred,
            "status": status_code,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now,
            **extra
        })
        _save("request_logs.json", logs)

    def _select_ambient_client():
        # If a client_id was provided, validate it exists and is usable.
        if isinstance(client_id, str):
            for c in clients:
                if c.get("client_id") == client_id and c.get("status") in ("active", "suspended"):
                    return c
            return None
        return None

    # Rate limit / quota (best-effort based on request_logs if present; otherwise no enforcement)
    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        # Simple per-client rolling window: 120 req/min; daily quota: 10000
        # Count only if client_id can be resolved
        cid = client_id if isinstance(client_id, str) else None
        if not cid:
            return None
        one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
        day_ago = (datetime.datetime.utcnow() - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("client_id") != cid:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                if ts >= day_ago:
                    per_day += 1
                if ts >= one_min_ago:
                    per_min += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim = _check_limits()
    if lim:
        _record_audit(429, None, {"client_id": client_id})
        return lim

    # Validate inputs
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-HJKMNP-TV-Z]{18,}$", client_id):
        _record_audit(400, None, {"client_id": client_id})
        return _err("VALIDATION_ERROR", "client_id is missing or malformed")
    if not isinstance(name, str) or not name.strip():
        _record_audit(400, None, {"client_id": client_id})
        return _err("VALIDATION_ERROR", "name is required")
    if settings is not None and not isinstance(settings, dict):
        _record_audit(400, None, {"client_id": client_id})
        return _err("VALIDATION_ERROR", "settings must be an object")
    if schedule is not None and not isinstance(schedule, dict):
        _record_audit(400, None, {"client_id": client_id})
        return _err("VALIDATION_ERROR", "schedule must be an object")
    if sequence_steps is not None and not isinstance(sequence_steps, list):
        _record_audit(400, None, {"client_id": client_id})
        return _err("VALIDATION_ERROR", "sequence_steps must be an array")

    # AuthZ / tenancy scope
    client = _select_ambient_client()
    if not client:
        # If client exists but deleted => NOT_FOUND is reasonable for tenant isolation
        exists = any(c.get("client_id") == client_id for c in clients)
        _record_audit(404 if exists else 404, None, {"client_id": client_id})
        return _err("NOT_FOUND", "client_id not found")

    # Enforce unique(client_id, lower(name)) where status != 'deleted'
    lname = name.strip().lower()
    for cmp in campaigns:
        if cmp.get("client_id") == client_id and cmp.get("status") != "deleted" and isinstance(cmp.get("name"), str) and cmp.get("name").strip().lower() == lname:
            _record_audit(409, None, {"client_id": client_id})
            return _err("CONFLICT", "campaign name already exists for this client")

    # Defaults
    default_settings = {
        "tracking": {"open": True, "click": True},
        "sending_limits": {"max_per_day": 0, "max_per_mailbox_per_day": 0},
        "reply_handling": {"auto_pause_on_reply": True},
        "unsubscribe": {"enabled": True},
        "allow_non_contiguous_sequence_numbers": False
    }
    default_schedule = {
        "days_of_week": ["mon", "tue", "wed", "thu", "fri"],
        "daily_start_time": "09:00",
        "daily_end_time": "17:00",
        "timezone": "UTC",
        "throttling": {"enabled": False},
        "holidays": []
    }

    new_settings = default_settings if settings is None else settings
    new_schedule = default_schedule if schedule is None else schedule
    new_sequence = [] if sequence_steps is None else sequence_steps

    # Validate minimal JSON schema assumptions for constraints
    if not isinstance(new_settings, dict) or not isinstance(new_schedule, dict):
        _record_audit(400, None, {"client_id": client_id})
        return _err("VALIDATION_ERROR", "settings and schedule must be valid objects")

    if not isinstance(new_sequence, list):
        _record_audit(400, None, {"client_id": client_id})
        return _err("VALIDATION_ERROR", "sequence_steps must be an array")

    # If provided sequence_steps, validate ordering/uniqueness of sequence_number if present
    seq_nums = []
    for i, st in enumerate(new_sequence):
        if not isinstance(st, dict):
            _record_audit(400, None, {"client_id": client_id})
            return _err("VALIDATION_ERROR", f"sequence_steps[{i}] must be an object")
        if "sequence_number" in st:
            if not isinstance(st["sequence_number"], int) or st["sequence_number"] < 1:
                _record_audit(400, None, {"client_id": client_id})
                return _err("VALIDATION_ERROR", f"sequence_steps[{i}].sequence_number must be an integer >= 1")
            seq_nums.append(st["sequence_number"])
    if seq_nums:
        if len(set(seq_nums)) != len(seq_nums):
            _record_audit(400, None, {"client_id": client_id})
            return _err("VALIDATION_ERROR", "sequence_steps sequence_number must be unique")
        if seq_nums != sorted(seq_nums):
            _record_audit(400, None, {"client_id": client_id})
            return _err("VALIDATION_ERROR", "sequence_steps must be sorted by sequence_number")

    # Create
    campaign_id = _mk_id("sl_cmp_")
    row = {
        "campaign_id": campaign_id,
        "client_id": client_id,
        "name": name.strip(),
        "status": "draft",
        "settings": new_settings,
        "schedule": new_schedule,
        "sequence_steps": new_sequence if isinstance(new_sequence, list) else [],
        "analytics_daily_rollups": None,
        "downloads": None,
        "deleted_at": None,
        "created_at": now,
        "updated_at": now
    }
    campaigns.append(row)
    _save("campaigns.json", campaigns)

    _record_audit(200, None, {"client_id": client_id, "campaign_id": campaign_id})
    return {"campaign": row}

