def smartlead_update_campaign_status(campaign_id, status, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    clients = _load("clients.json")
    campaigns = _load("campaigns.json")

    def _mk_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = uuid.uuid4().int
        s = ""
        for _ in range(18):
            s = alphabet[raw % len(alphabet)] + s
            raw //= len(alphabet)
        return f"{prefix}{s}"

    def _record_audit(status_code, extra=None):
        extra = extra or {}
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": _mk_id("sl_req_"),
            "endpoint": "smartlead_update_campaign_status",
            "credential_id": None,
            "status": status_code,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now,
            **extra
        })
        _save("request_logs.json", logs)

    def _check_limits(client_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or not client_id:
            return None
        one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
        day_ago = (datetime.datetime.utcnow() - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("client_id") != client_id:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                if ts >= day_ago:
                    per_day += 1
                if ts >= one_min_ago:
                    per_min += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(campaign_id, str) or not re.match(r"^sl_cmp_[0-9A-HJKMNP-TV-Z]{18,}$", campaign_id):
        _record_audit(400, {"campaign_id": campaign_id})
        return _err("VALIDATION_ERROR", "campaign_id is missing or malformed")
    allowed = {"draft", "active", "paused", "completed", "archived", "deleted"}
    if not isinstance(status, str) or status not in allowed:
        _record_audit(400, {"campaign_id": campaign_id})
        return _err("VALIDATION_ERROR", "status must be one of: draft, active, paused, completed, archived, deleted")

    idx = None
    for i, c in enumerate(campaigns):
        if c.get("campaign_id") == campaign_id:
            idx = i
            break
    if idx is None:
        _record_audit(404, {"campaign_id": campaign_id})
        return _err("NOT_FOUND", "campaign not found")

    camp = campaigns[idx]
    client_id = camp.get("client_id")

    lim = _check_limits(client_id)
    if lim:
        _record_audit(429, {"client_id": client_id, "campaign_id": campaign_id})
        return lim

    client_ok = any(cl.get("client_id") == client_id and cl.get("status") in ("active", "suspended") for cl in clients)
    if not client_ok:
        _record_audit(401, {"client_id": client_id, "campaign_id": campaign_id})
        return _err("UNAUTHORIZED", "No authorized client context found for this campaign")

    current = camp.get("status")
    transitions = {
        "draft": {"active", "archived", "deleted"},
        "active": {"paused", "completed", "archived", "deleted"},
        "paused": {"active", "archived", "deleted"},
        "completed": {"archived", "deleted"},
        "archived": {"deleted"},
        "deleted": set()
    }

    if current == status:
        # Idempotent: no-op allowed but must still be a real effect? For status update, treat as idempotent success.
        _record_audit(200, {"client_id": client_id, "campaign_id": campaign_id})
        return {"campaign": camp}

    if current not in transitions or status not in transitions[current]:
        _record_audit(409, {"client_id": client_id, "campaign_id": campaign_id, "from_status": current, "to_status": status})
        return _err("INVALID_TRANSITION", f"cannot transition campaign from {current} to {status}")

    # Enforce constraints for activating
    if status == "active":
        steps = camp.get("sequence_steps")
        if not isinstance(steps, list) or len(steps) < 1:
            _record_audit(400, {"client_id": client_id, "campaign_id": campaign_id})
            return _err("VALIDATION_ERROR", "cannot activate campaign without at least one sequence step")
        sch = camp.get("schedule")
        tz = sch.get("timezone") if isinstance(sch, dict) else None
        if tz is None:
            _record_audit(400, {"client_id": client_id, "campaign_id": campaign_id})
            return _err("VALIDATION_ERROR", "cannot activate campaign without schedule.timezone")

    # Apply transition
    camp["status"] = status
    if status == "deleted":
        camp["deleted_at"] = now
    camp["updated_at"] = now

    campaigns[idx] = camp
    _save("campaigns.json", campaigns)
    _record_audit(200, {"client_id": client_id, "campaign_id": campaign_id, "from_status": current, "to_status": status})
    return {"campaign": camp}

def smartlead_get_campaign(campaign_id, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_campaign"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, client_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "log_id": "sl_req_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "client_id": client_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits(client_id):
        clients = _load("clients.json")
