        if isinstance(quota, int) and quota > 0 and per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _validate_steps(steps):
        if not isinstance(steps, list):
            return _err("VALIDATION_ERROR", "sequence_steps must be an array.", field="sequence_steps")
        for i, st in enumerate(steps):
            if not isinstance(st, dict):
                return _err("VALIDATION_ERROR", "Each sequence step must be an object.", field="sequence_steps", index=i)

        seq_nums = []
        for i, st in enumerate(steps):
            if "sequence_number" not in st:
                return _err("VALIDATION_ERROR", "sequence_number is required for each step.", field="sequence_steps", index=i)
            sn = st.get("sequence_number")
            if not isinstance(sn, int):
                return _err("VALIDATION_ERROR", "sequence_number must be an integer.", field="sequence_steps", index=i)
            if sn < 1:
                return _err("VALIDATION_ERROR", "sequence_number must be >= 1.", field="sequence_steps", index=i)
            seq_nums.append(sn)

        if len(set(seq_nums)) != len(seq_nums):
            return _err("VALIDATION_ERROR", "sequence_number values must be unique.", field="sequence_steps")

        seq_sorted = sorted(seq_nums)
        if seq_sorted and seq_sorted[0] != 1:
            return _err("VALIDATION_ERROR", "sequence_number must start at 1.", field="sequence_steps")
        for a, b in zip(seq_sorted, seq_sorted[1:]):
            if b != a + 1:
                return _err("VALIDATION_ERROR", "sequence_number must be contiguous.", field="sequence_steps")

        # Ensure stored order is sorted by sequence_number
        steps_sorted = sorted(steps, key=lambda x: x.get("sequence_number"))
