            return err

        campaigns = _load("campaigns.json")
        idx = None
        camp = None
        for i, c in enumerate(campaigns):
            if c.get("campaign_id") == campaign_id:
                idx = i
                camp = c
                break
        if camp is None:
            _log("NOT_FOUND", meta={"campaign_id": campaign_id})
            return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

