            _log("UNAUTHORIZED", client_id=client_id, meta={"campaign_id": campaign_id})
            return _err("UNAUTHORIZED", "You don’t have access to this campaign.")

        lim = _check_limits(client_id)
        if lim:
            _log(lim["error"]["code"], client_id=client_id, meta={"campaign_id": campaign_id})
            return lim

        if camp.get("status") == "deleted":
            _log("CONFLICT", client_id=client_id, meta={"campaign_id": campaign_id, "reason": "campaign_deleted"})
            return _err("CONFLICT", "Cannot modify a deleted campaign.", campaign_id=campaign_id)

        camp["sequence_steps"] = steps_sorted
        camp["updated_at"] = _now()
        campaigns[idx] = camp
        _save("campaigns.json", campaigns)

        _log("OK", client_id=client_id, meta={"campaign_id": campaign_id, "steps": len(steps_sorted)})
        return {"campaign_id": campaign_id, "sequence_steps": camp.get("sequence_steps", [])}
    except Exception as e:
        _log("FAILED", meta={"exception": str(e)})
        return _err("CONFLICT", "Unexpected error while processing request.", detail=str(e))

