        if not isinstance(client_id, str) or not client_id:
            _log("UNAUTHORIZED", meta={"campaign_id": campaign_id})
            return _err("UNAUTHORIZED", "You don’t have access to this campaign.")

        clients = _load("clients.json")
        if not any(x.get("client_id") == client_id and x.get("status") == "active" for x in clients):
            _log("UNAUTHORIZED", client_id=client_id, meta={"campaign_id": campaign_id})
            return _err("UNAUTHORIZED", "You don’t have access to this campaign.")

        lim = _check_limits(client_id)
        if lim:
            _log(lim["error"]["code"], client_id=client_id, meta={"campaign_id": campaign_id})
            return lim

        _log("OK", client_id=client_id, meta={"campaign_id": campaign_id})
        return {"campaign_id": campaign_id, "sequence_steps": camp.get("sequence_steps") or []}
    except Exception as e:
        _log("FAILED", meta={"exception": str(e)})
        return _err("CONFLICT", "Unexpected error while processing request.", detail=str(e))

def smartlead_get_campaigns_by_lead(lead_id, include_deleted=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request logging + simple rate limiting (shared helper)
    def _log(endpoint, status, client_id=None, credential_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "ts": now,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # 120 requests per rolling minute per client (or global if unknown yet)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs[-2000:]):
            ts = r.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("smartlead_get_campaigns_by_lead", "error", error_code="RATE_LIMIT")
        return rl

    # Validate
    if not isinstance(lead_id, str) or not re.match(r"^sl_led_01H[A-Z0-9]{15,}$", lead_id):
        _log("smartlead_get_campaigns_by_lead", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "lead_id is invalid.")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("smartlead_get_campaigns_by_lead", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean when provided.")

    # Ambient auth: resolve any active client that owns this lead. If none, NOT_FOUND.
    leads = _load("leads.json")
    if not isinstance(leads, list):
        leads = []
    lead = next((x for x in leads if x.get("lead_id") == lead_id), None)
    if not lead:
        _log("smartlead_get_campaigns_by_lead", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Lead not found.")
    client_id = lead.get("client_id")
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    client = next((c for c in clients if c.get("client_id") == client_id and c.get("status") != "deleted"), None)
    if not client:
        _log("smartlead_get_campaigns_by_lead", "error", client_id=client_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized for this lead.")

    # Fetch campaigns referenced by memberships
    memberships = lead.get("campaign_memberships") or []
    if not isinstance(memberships, list):
        memberships = []

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []

    campaign_ids = []
    seen = set()
    for m in memberships:
        if not isinstance(m, dict):
            continue
        cid = m.get("campaign_id")
        if isinstance(cid, str) and cid not in seen:
            seen.add(cid)
            campaign_ids.append(cid)

    result = []
    for cid in campaign_ids:
        camp = next((c for c in campaigns if c.get("campaign_id") == cid), None)
        # If campaign referenced but missing, ignore (integrity issue), but do not error.
        if not camp:
            continue
        # Cross-client access is rejected: if any membership points to another client, treat as forbidden.
        if camp.get("client_id") != client_id:
            _log("smartlead_get_campaigns_by_lead", "error", client_id=client_id, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Not authorized to access one or more campaigns for this lead.")
        st = camp.get("status")
        if not include_deleted:
            if st in ("deleted", "archived"):
                continue
        result.append(camp)

    _log("smartlead_get_campaigns_by_lead", "ok", client_id=client_id, meta={"returned": len(result)})
    return {
        "campaigns": result,
        "meta": {"lead_id": lead_id, "total": len(result), "include_deleted": bool(include_deleted)}
    }

def smartlead_export_campaign_leads(campaign_id, status=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, client_id=None, meta=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "smartlead_export_campaign_leads",
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate inputs (relax pattern to match actual datastore sl_cmp_01J... too)
    if not isinstance(campaign_id, str) or not re.match(r"^sl_cmp_01[0-9A-Z]{16,}$", campaign_id):
        _log("error", meta={"field": "campaign_id"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")
    if status is not None and status not in ("active", "suppressed", "deleted"):
        _log("error", meta={"field": "status"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, suppressed, deleted.", field="status")
    if limit is None:
        limit = 1000
    if not isinstance(limit, int) or limit < 1 or limit > 5000:
        _log("error", meta={"field": "limit"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 5000.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", meta={"field": "cursor"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.", field="cursor")

    # Resolve campaign & client scope
    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    campaign = None
    for c in campaigns:
        if isinstance(c, dict) and c.get("campaign_id") == campaign_id:
            campaign = c
            break
    if campaign is None:
        _log("error", meta={"campaign_id": campaign_id}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client_id = campaign.get("client_id")
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    client = None
    for cl in clients:
        if isinstance(cl, dict) and cl.get("client_id") == client_id and cl.get("status") in ("active", "suspended"):
            client = cl
            break
    if client is None:
        _log("error", client_id=client_id, meta={"campaign_id": campaign_id}, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible client context for this campaign.", client_id=client_id)

    # Rate limit per client (observed via request logs)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for r in reversed(logs[-5000:]):
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "smartlead_export_campaign_leads":
            continue
        if r.get("client_id") != client_id:
            continue
        dt = _parse_ts(r.get("timestamp"))
        if not dt:
            continue
        if dt < cutoff:
            break
        recent += 1
        if recent >= 60:
            _log("error", client_id=client_id, meta={"window_s": 60, "limit": 60}, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_s=60, limit=60)

    leads = _load("leads.json")
    if not isinstance(leads, list):
        leads = []

    # Build export set: leads for this client with membership in campaign
    export_rows = []
    for ld in leads:
        if not isinstance(ld, dict):
            continue
        if ld.get("client_id") != client_id:
            continue
        memberships = ld.get("campaign_memberships") or []
        if not isinstance(memberships, list):
            continue
        mem = None
        for m in memberships:
            if isinstance(m, dict) and m.get("campaign_id") == campaign_id:
                mem = m
                break
        if not mem:
            continue
        if status is not None and ld.get("status") != status:
            continue
        export_rows.append(ld)

    # Stable order: created_at, then lead_id
    def _sort_key(x):
        ca = x.get("created_at") if isinstance(x, dict) else None
        return (ca if isinstance(ca, str) else "", x.get("lead_id") if isinstance(x, dict) else "")
    export_rows.sort(key=_sort_key)

    # Cursor: opaque but implement as base64("offset:<n>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"=" * (-len(cursor) % 4)).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
            else:
                _log("error", client_id=client_id, meta={"field": "cursor"}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _log("error", client_id=client_id, meta={"field": "cursor"}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")

    page = export_rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(export_rows)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Record download entry in campaign.downloads (always; even for empty page, this endpoint represents an export chunk request)
    if campaign.get("downloads") is None or not isinstance(campaign.get("downloads"), list):
        campaign["downloads"] = []
    download_id = "sl_dwl_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").upper()
    campaign["downloads"].append({
        "download_id": download_id,
        "requested_at": now_iso,
        "requested_by": client_id,
        "format": "csv",
        "filters": {
            "lead_status": status,
            "cursor": cursor,
            "limit": limit
        },
        "row_count": len(page)
    })
    campaign["updated_at"] = now_iso
    _save("campaigns.json", campaigns)

    _log("ok", client_id=client_id, meta={"campaign_id": campaign_id, "returned": len(page), "total": len(export_rows)})

    return {
        "campaign_id": campaign_id,
        "client_id": client_id,
        "download_id": download_id,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "total": len(export_rows),
        "data": page
    }

def smartlead_delete_campaign(campaign_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, client_id=None, meta=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "smartlead_delete_campaign",
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate (accept sl_cmp_01J... too)
    if not isinstance(campaign_id, str) or not re.match(r"^sl_cmp_01[0-9A-Z]{16,}$", campaign_id):
        _log("error", meta={"field": "campaign_id"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    idx = None
    campaign = None
    for i, c in enumerate(campaigns):
        if isinstance(c, dict) and c.get("campaign_id") == campaign_id:
            idx = i
            campaign = c
            break
    if campaign is None:
        _log("error", meta={"campaign_id": campaign_id}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client_id = campaign.get("client_id")

    # Ensure client exists and is not deleted
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    ok_client = False
    for cl in clients:
        if isinstance(cl, dict) and cl.get("client_id") == client_id and cl.get("status") in ("active", "suspended"):
            ok_client = True
            break
    if not ok_client:
        _log("error", client_id=client_id, meta={"campaign_id": campaign_id}, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible client context for this campaign.", client_id=client_id)

    # Rate limit per client
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in reversed(logs[-5000:]):
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "smartlead_delete_campaign":
            continue
        if r.get("client_id") != client_id:
            continue
        dt = _parse_ts(r.get("timestamp"))
        if not dt:
            continue
        if dt < cutoff:
            break
        recent += 1
        if recent >= 30:
            _log("error", client_id=client_id, meta={"window_s": 60, "limit": 30}, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_s=60, limit=30)

    # Enforce hard-delete policy: only if no non-deleted webhook records reference it
    iap = _load("integrations_and_procurement.json")
    if not isinstance(iap, list):
        iap = []
    for rec in iap:
        if not isinstance(rec, dict):
            continue
        if rec.get("record_type") != "campaign_webhook":
            continue
        if rec.get("campaign_id") != campaign_id:
            continue
        if rec.get("status") in ("active", "inactive"):
            _log("error", client_id=client_id, meta={"campaign_id": campaign_id, "blocking_record_id": rec.get("record_id")}, error_code="CONFLICT")
            return _err("CONFLICT", "Cannot hard delete campaign while non-deleted webhooks still reference it.", campaign_id=campaign_id, blocking_record_id=rec.get("record_id"))

    # Hard delete campaign row
    deleted_row = campaigns.pop(idx)
    _save("campaigns.json", campaigns)

    _log("ok", client_id=client_id, meta={"campaign_id": campaign_id, "deleted": True})
    return {"campaign_id": campaign_id, "client_id": client_id, "deleted": True, "campaign": deleted_row}

def smartlead_get_campaign_analytics_by_date(campaign_id, start_date, end_date, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_campaign_analytics_by_date"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _parse_date(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format.", field=field)
        try:
            d = datetime.date.fromisoformat(s)
            return d, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid date in YYYY-MM-DD format.", field=field)

    def _get_client_by_campaign(camp_row):
        cid = camp_row.get("client_id")
        clients = _load("clients.json")
        if not isinstance(clients, list):
            clients = []
        for cl in clients:
            if isinstance(cl, dict) and cl.get("client_id") == cid and cl.get("status") in ("active", "suspended"):
                return cl
        return None

    def _rate_limit_check(client_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        units = 0
        # lightweight scan of recent tail
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if client_id and r.get("client_id") != client_id:
                continue
            ts = r.get("timestamp") or r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            ep = r.get("endpoint")
            units += 2 if ep in (
                "smartlead_get_campaign_analytics_by_date",
                "smartlead_get_campaign_statistics_by_date",
                "smartlead_get_campaign_statistics",
                "smartlead_get_campaign_top_level_analytics",
                "smartlead_get_campaign_lead_statistics",
                "smartlead_get_campaign_mailbox_statistics",
                "smartlead_get_campaign_sequence_analytics",
            ) else 1
            if units >= 120:
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60)
        return None

    def _log(status, client_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate (be permissive: accept any sl_cmp_* id present in store even if regex is narrower than real ids)
    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is required.", field="campaign_id")
    campaign_id = campaign_id.strip()
    if re.match(r"^sl_cmp_[0-9A-Z]{10,}$", campaign_id) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")

    sd, e1 = _parse_date(start_date, "start_date")
    if e1:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "start_date"})
        return e1
    ed, e2 = _parse_date(end_date, "end_date")
    if e2:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "end_date"})
        return e2
    if sd > ed:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "start_date"})
        return _err("VALIDATION_ERROR", "start_date must be on or before end_date.", field="start_date")

    # Load campaign
    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = None
    for c in campaigns:
        if isinstance(c, dict) and c.get("campaign_id") == campaign_id:
            camp = c
            break
    if not camp or camp.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND", meta={"campaign_id": campaign_id})
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    # Resolve access context from store (ambient auth): if campaign's client exists and is active/suspended, allow
    client = _get_client_by_campaign(camp)
    if not client:
        _log("error", error_code="UNAUTHORIZED", meta={"campaign_id": campaign_id})
        return _err("UNAUTHORIZED", "You do not have access to this campaign.", campaign_id=campaign_id)

    rl = _rate_limit_check(client.get("client_id"))
    if rl:
        _log("error", client_id=client.get("client_id"), error_code="RATE_LIMIT", meta={"campaign_id": campaign_id})
        return rl

    rollups = camp.get("analytics_daily_rollups") or []
    if not isinstance(rollups, list):
        rollups = []

    # Aggregate by date within inclusive range
    metric_keys = [
        "sent", "delivered", "opened", "clicked", "replied", "bounced", "unsubscribed", "complained",
        "spam", "failed", "unique_opens", "unique_clicks"
    ]
    by_date = {}
    total = {k: 0 for k in metric_keys}

    def _coerce_int(v):
        if isinstance(v, bool) or v is None:
            return 0
        if isinstance(v, int):
            return v
        if isinstance(v, float):
            return int(v)
        if isinstance(v, str):
            try:
                return int(float(v.strip()))
            except Exception:
                return 0
        return 0

    for r in rollups:
        if not isinstance(r, dict):
            continue
        dstr = r.get("date")
        if not isinstance(dstr, str):
            continue
        try:
            d = datetime.date.fromisoformat(dstr)
        except Exception:
            continue
        if d < sd or d > ed:
            continue
        key = d.isoformat()
        if key not in by_date:
            by_date[key] = {k: 0 for k in metric_keys}
        for k in metric_keys:
            v = _coerce_int(r.get(k))
            by_date[key][k] += v
            total[k] += v

    rows = []
    cur = sd
    while cur <= ed:
        k = cur.isoformat()
        row = {"date": k, **({m: by_date.get(k, {}).get(m, 0) for m in metric_keys})}
        rows.append(row)
        cur += datetime.timedelta(days=1)

    resp = {
        "campaign_id": campaign_id,
        "client_id": client.get("client_id"),
        "start_date": sd.isoformat(),
        "end_date": ed.isoformat(),
        "totals": total,
        "daily": rows
    }
    _log("success", client_id=client.get("client_id"), meta={"campaign_id": campaign_id, "days": len(rows)})
    return resp

