            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validation (relax pattern to accept existing ids in store while still rejecting obvious bad types)
    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is required.", field="campaign_id")
    campaign_id = campaign_id.strip()
    if re.match(r"^sl_cmp_[0-9A-Z]{10,}$", campaign_id) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is malformed.", field="campaign_id")

    if not isinstance(sequence_step, int):
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "sequence_step"})
        return _err("VALIDATION_ERROR", "sequence_step must be an integer.", field="sequence_step")
    if sequence_step < 1:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "sequence_step"})
        return _err("VALIDATION_ERROR", "sequence_step is out of range.", field="sequence_step", minimum=1)

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list): campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("campaign_id") == campaign_id), None)
    if not camp:
        _log("error", error_code="NOT_FOUND", meta={"campaign_id": campaign_id})
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client_id = camp.get("client_id")
    clients = _load("clients.json")
    if not isinstance(clients, list): clients = []
    client = next((cl for cl in clients if isinstance(cl, dict) and cl.get("client_id") == client_id and cl.get("status") in ("active", "suspended")), None)
    if not client:
        _log("error", client_id=client_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to this campaign.", campaign_id=campaign_id)

    # Business rule: analytics read from analytics_daily_rollups filtered by campaign_id and sequence_number.
    rollups = camp.get("analytics_daily_rollups")
    if not isinstance(rollups, list):
        rollups = []

    step_rollups = []
    for r in rollups:
        if not isinstance(r, dict):
            continue
        # tolerate different keys: sequence_number or sequence_step
        seq = r.get("sequence_number", r.get("sequence_step"))
        if seq == sequence_step:
            step_rollups.append(r)

    # IMPORTANT: A read whose filters match nothing returns empty results, not NOT_FOUND.
    # Campaign existence already validated above.
    # Return an envelope with some helpful metadata.
    out = {
        "campaign_id": campaign_id,
        "sequence_step": sequence_step,
        "rollups": step_rollups,
        "total": len(step_rollups)
    }
    _log("ok", client_id=client_id)
