def smartlead_list_leads(client_id, campaign_id=None, status=None, q=None, cursor=None, limit=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "request_id": "sl_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "smartlead_list_leads",
            "status": status_code,
            "client_id": client_id,
            "latency_ms": latency_ms,
            "timestamp": now
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "smartlead_list_leads":
                continue
            if r.get("client_id") != client_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                continue
            cnt += 1
            if cnt > 240:
                return False, _err("RATE_LIMIT", "Rate limit exceeded for this endpoint.")
        return True, None

    ok, rl_err = _rate_limit_check()
    if not ok:
        _log(429)
        return rl_err

    # Validate inputs
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_01H[A-Z0-9]{15,}$", client_id or ""):
        _log(400)
        return _err("VALIDATION_ERROR", "client_id is invalid.", field="client_id")

    if campaign_id is not None:
        if not isinstance(campaign_id, str) or not re.match(r"^sl_cmp_01H[A-Z0-9]{15,}$", campaign_id or ""):
            _log(400)
            return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")

    if status is not None:
        if status not in ("active", "suppressed", "deleted"):
            _log(400)
            return _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=["active", "suppressed", "deleted"])

    if q is not None and not isinstance(q, str):
        _log(400)
        return _err("VALIDATION_ERROR", "q must be a string.", field="q")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "email"):
        _log(400)
        return _err("VALIDATION_ERROR", "sort_by is invalid.", field="sort_by", allowed=["created_at", "updated_at", "email"])

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        _log(400)
        return _err("VALIDATION_ERROR", "sort_order is invalid.", field="sort_order", allowed=["asc", "desc"])

    # Ensure client exists and accessible
    clients = _load("clients.json")
    if not isinstance(clients, list):
        _log(500)
        return _err("CONFLICT", "Datastore corrupted for clients.")
    client = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
    if not client or client.get("status") != "active":
        _log(401)
        return _err("UNAUTHORIZED", "Not authorized to access this client.", client_id=client_id)

    # If campaign filter, validate campaign exists, owned by same client, and not deleted
    if campaign_id is not None:
        campaigns = _load("campaigns.json")
        if not isinstance(campaigns, list):
            _log(500)
            return _err("CONFLICT", "Datastore corrupted for campaigns.")
        camp = next((c for c in campaigns if isinstance(c, dict) and c.get("campaign_id") == campaign_id), None)
        if not camp or camp.get("status") == "deleted":
            _log(404)
            return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)
        if camp.get("client_id") != client_id:
            _log(400)
            return _err("VALIDATION_ERROR", "campaign_id does not belong to the specified client_id.", field="campaign_id")

    # Decode cursor (offset-based cursor, opaque)
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log(400)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            raw_s = raw.decode("utf-8", errors="strict")
            if not raw_s.startswith("off:"):
                _log(400)
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            start = int(raw_s.split(":", 1)[1])
            if start < 0:
                raise ValueError()
        except Exception:
            _log(400)
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    leads = _load("leads.json")
    if not isinstance(leads, list):
        _log(500)
        return _err("CONFLICT", "Datastore corrupted for leads.")

    qq = (q or "").strip().lower()
    def _matches_text(ld):
        if not qq:
            return True
        fields = [
            ld.get("email"), ld.get("first_name"), ld.get("last_name"),
            ld.get("company"), ld.get("title"), ld.get("phone"),
            ld.get("linkedin_url"), ld.get("website")
        ]
        blob = " ".join([str(x).lower() for x in fields if isinstance(x, str)])
        return qq in blob

    def _in_campaign(ld):
        if campaign_id is None:
            return True
        mems = ld.get("campaign_memberships") or []
        if not isinstance(mems, list):
            return False
        for m in mems:
            if isinstance(m, dict) and m.get("campaign_id") == campaign_id:
                return True
        return False

    filtered = []
    for ld in leads:
        if not isinstance(ld, dict):
            continue
        if ld.get("client_id") != client_id:
            continue
        if status is not None and ld.get("status") != status:
            continue
        if not _in_campaign(ld):
            continue
        if not _matches_text(ld):
            continue
        filtered.append(ld)

    # Sorting
    def _sort_key(ld):
        if sort_by in ("created_at", "updated_at"):
            v = ld.get(sort_by)
            return ("" if v is None else str(v), str(ld.get("lead_id", "")))
        if sort_by == "email":
            v = ld.get("email")
            return ("" if v is None else str(v).lower(), str(ld.get("lead_id", "")))
        return (str(ld.get("lead_id", "")),)

    reverse = (sort_order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[start:start + limit]
    next_off = start + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "items": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log(200, extra={"result_count": len(page)})
    return resp

