        recent += 1
        if recent > 120:
            _log("error", client_id=client_id, meta={"window_s": 60, "limit": 120}, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded for this endpoint.", window_s=60, limit=120)

    leads_store = _load("leads.json")
    if not isinstance(leads_store, list):
        leads_store = []

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").upper()

    # Upsert by (client_id, lower(email)) among non-deleted
    email_key = email_norm.lower()
    lead_row = None
    lead_idx = None
    for i, ld in enumerate(leads_store):
        if not isinstance(ld, dict):
            continue
        if ld.get("client_id") != client_id:
            continue
        if ld.get("status") == "deleted":
            continue
        if isinstance(ld.get("email"), str) and ld.get("email").lower() == email_key:
            lead_row = ld
            lead_idx = i
            break

    created = False
    updated = False

    if lead_row is None:
        created = True
        lead_row = {
            "lead_id": _gen_id("sl_led_"),
            "client_id": client_id,
            "email": email_norm,
            "first_name": lead.get("first_name"),
            "last_name": lead.get("last_name"),
            "company": lead.get("company"),
            "title": lead.get("title"),
            "phone": lead.get("phone"),
            "linkedin_url": lead.get("linkedin_url"),
            "website": lead.get("website"),
            "custom_fields": lead.get("custom_fields"),
            "status": "active",
            "campaign_memberships": [],
            "created_at": now_iso,
            "updated_at": now_iso
        }
        leads_store.append(lead_row)
        lead_idx = len(leads_store) - 1
    else:
        # Update base fields provided (do not overwrite with None unless explicitly provided as None)
        for f in ("first_name", "last_name", "company", "title", "phone", "linkedin_url", "website", "custom_fields"):
            if f in lead:
                lead_row[f] = lead.get(f)
                updated = True
        # Keep email and client_id stable; bump updated_at if changed fields
        if updated:
            lead_row["updated_at"] = now_iso

    # Add/update campaign membership (unique per campaign)
    memberships = lead_row.get("campaign_memberships")
    if not isinstance(memberships, list):
        memberships = []
        lead_row["campaign_memberships"] = memberships

    mem = None
    for m in memberships:
        if isinstance(m, dict) and m.get("campaign_id") == campaign_id:
            mem = m
            break

    membership_changed = False
    if mem is None:
        membership_changed = True
        mem = {
            "campaign_id": campaign_id,
            "membership_id": _gen_id("sl_mem_"),
            "campaign_lead_status": "queued",
            "added_at": now_iso,
            "last_status_at": now_iso,
            "sequence_position": 0,
            "last_sent_at": None
        }
        memberships.append(mem)
    else:
        # Idempotent: keep membership but refresh timestamps to reflect "add" action
        mem["last_status_at"] = now_iso
        membership_changed = True

    if created or updated or membership_changed:
        lead_row["updated_at"] = now_iso
        leads_store[lead_idx] = lead_row
        _save("leads.json", leads_store)

    _log("ok", client_id=client_id, meta={"campaign_id": campaign_id, "created": created, "updated": updated})

    return {"lead": lead_row, "campaign_id": campaign_id, "client_id": client_id, "created": created, "updated": updated}

def smartlead_update_lead(lead_id, email=None, first_name=None, last_name=None, company=None, title=None, phone=None, linkedin_url=None, website=None, custom_fields=None, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    reqlog = _load("request_logs.json")
    usage = _load("usage_counters.json")

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, client_id=None, meta=None):
        nonlocal reqlog, usage
        ts = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "request_id": "req_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(16)),
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status,
            "latency_ms": latency_ms,
            "credential_used": credential_used,
            "client_id": client_id,
            "meta": meta or {}
        })
        # Simple global counters (best-effort schema-agnostic)
        key = endpoint
        found = False
        for row in usage:
            if isinstance(row, dict) and row.get("key") == key:
                row["count"] = int(row.get("count", 0)) + 1
                row["updated_at"] = ts
                found = True
                break
        if not found:
            usage.append({"key": key, "count": 1, "updated_at": ts})
        _save("request_logs.json", reqlog)
        _save("usage_counters.json", usage)

    endpoint = "smartlead_update_lead"

    # Basic rate limiting based on request_logs.json (if present)
    def _rate_limited():
        # 300 req / 60s globally
        window_s = 60
        limit = 300
        now = datetime.datetime.utcnow()
        cnt = 0
        for r in reqlog[-2000:]:
            try:
                ts = r.get("timestamp")
                if not ts:
                    continue
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                if (now - dt).total_seconds() <= window_s:
                    cnt += 1
            except Exception:
                continue
        return cnt >= limit

    if _rate_limited():
        _log(endpoint, "error", meta={"code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate lead_id
    if not isinstance(lead_id, str) or not re.match(r"^sl_led_01H[0-9A-Z]{15,}$", lead_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "lead_id is invalid.", field="lead_id")

    # Validate provided fields types
    for fname, fval in [
        ("email", email), ("first_name", first_name), ("last_name", last_name),
        ("company", company), ("title", title), ("phone", phone),
        ("linkedin_url", linkedin_url), ("website", website)
    ]:
        if fval is not None and not isinstance(fval, str):
            _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{fname} must be a string.", field=fname)

    if custom_fields is not None and not isinstance(custom_fields, dict):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "custom_fields must be an object.", field="custom_fields")

    # Need at least one updatable field besides lead_id
    if all(v is None for v in [email, first_name, last_name, company, title, phone, linkedin_url, website, custom_fields]):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No fields provided to update.")

    leads = _load("leads.json")
    clients = _load("clients.json")
    campaigns = _load("campaigns.json")

    lead = None
    lead_idx = None
    for i, r in enumerate(leads):
        if isinstance(r, dict) and r.get("lead_id") == lead_id:
            lead = r
            lead_idx = i
            break

    if not lead:
        _log(endpoint, "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Lead not found.")

    client_id = lead.get("client_id")
    # Ambient auth: ensure there's at least one active client matching lead.client_id, else unauthorized.
    client_ok = False
    for c in clients:
        if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") == "active":
            client_ok = True
            break
    if not client_ok:
        _log(endpoint, "error", client_id=client_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authorized for this lead's client scope.")

    # Reject edits to deleted lead
    if lead.get("status") == "deleted":
        _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Cannot update a deleted lead.")

    # If email changes, enforce uniqueness (client_id, lower(email)) where status != deleted
    if email is not None:
        new_email = email.strip()
        if not new_email or "@" not in new_email:
            _log(endpoint, "error", client_id=client_id, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "email is invalid.", field="email")
        lower_new = new_email.lower()
        for r in leads:
            if not isinstance(r, dict):
                continue
            if r.get("lead_id") == lead_id:
                continue
            if r.get("client_id") == client_id and r.get("status") != "deleted":
                if isinstance(r.get("email"), str) and r.get("email").lower() == lower_new:
                    _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
                    return _err("CONFLICT", "A lead with this email already exists for this client.", field="email")
        lead["email"] = new_email

    # Update mutable fields
    if first_name is not None:
        lead["first_name"] = first_name
    if last_name is not None:
        lead["last_name"] = last_name
    if company is not None:
        lead["company"] = company
    if title is not None:
        lead["title"] = title
    if phone is not None:
        lead["phone"] = phone
    if linkedin_url is not None:
        lead["linkedin_url"] = linkedin_url
    if website is not None:
        lead["website"] = website
    if custom_fields is not None:
        lead["custom_fields"] = custom_fields

    # Consistency check: memberships must reference campaigns of same client if present
    memberships = lead.get("campaign_memberships", [])
    if memberships is None:
        memberships = []
    if not isinstance(memberships, list):
        _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Lead campaign_memberships is corrupted; cannot update lead.")
    camp_by_id = {c.get("campaign_id"): c for c in campaigns if isinstance(c, dict)}
    for m in memberships:
        if not isinstance(m, dict):
            _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "Lead campaign_memberships is corrupted; cannot update lead.")
        cid = m.get("campaign_id")
        if cid is None:
            continue
        camp = camp_by_id.get(cid)
        if not camp or camp.get("status") == "deleted":
            # Keep membership as-is (historical), but cross-client is not allowed
            # If missing campaign, treat as conflict in integrity.
            _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "Lead references a missing/deleted campaign; cannot update lead until fixed.", campaign_id=cid)
        if camp.get("client_id") != client_id:
            _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "Cross-client campaign membership detected; cannot update lead.", campaign_id=cid)

    lead["updated_at"] = _iso_now()
    leads[lead_idx] = lead
    _save("leads.json", leads)

    _log(endpoint, "ok", client_id=client_id)
    return {"lead": lead}

def smartlead_update_lead_status(lead_id, status, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    reqlog = _load("request_logs.json")
    usage = _load("usage_counters.json")

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, credential_used=None, client_id=None, meta=None):
        nonlocal reqlog, usage
        ts = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "request_id": "req_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(16)),
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status_s,
            "latency_ms": latency_ms,
            "credential_used": credential_used,
            "client_id": client_id,
            "meta": meta or {}
        })
        key = endpoint
        found = False
        for row in usage:
            if isinstance(row, dict) and row.get("key") == key:
                row["count"] = int(row.get("count", 0)) + 1
                row["updated_at"] = ts
                found = True
                break
        if not found:
            usage.append({"key": key, "count": 1, "updated_at": ts})
        _save("request_logs.json", reqlog)
        _save("usage_counters.json", usage)

    endpoint = "smartlead_update_lead_status"

    def _rate_limited():
        window_s = 60
        limit = 300
        now = datetime.datetime.utcnow()
        cnt = 0
        for r in reqlog[-2000:]:
            try:
                ts = r.get("timestamp")
                if not ts:
                    continue
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                if (now - dt).total_seconds() <= window_s:
                    cnt += 1
            except Exception:
                continue
        return cnt >= limit

    if _rate_limited():
        _log(endpoint, "error", meta={"code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if not isinstance(lead_id, str) or not re.match(r"^sl_led_01H[0-9A-Z]{15,}$", lead_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "lead_id is invalid.", field="lead_id")

    if status not in ("active", "suppressed", "deleted"):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=["active", "suppressed", "deleted"])

    leads = _load("leads.json")
    clients = _load("clients.json")

    lead = None
    lead_idx = None
    for i, r in enumerate(leads):
        if isinstance(r, dict) and r.get("lead_id") == lead_id:
            lead = r
            lead_idx = i
            break
    if not lead:
        _log(endpoint, "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Lead not found.")

    client_id = lead.get("client_id")
    client_ok = any(isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") == "active" for c in clients)
    if not client_ok:
        _log(endpoint, "error", client_id=client_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authorized for this lead's client scope.")

    transitions = {
        "active": {"suppressed", "deleted"},
        "suppressed": {"active", "deleted"},
        "deleted": set()
    }
    cur = lead.get("status")
    if cur not in transitions:
        _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Lead has an invalid current status.", current_status=cur)

    if status == cur:
        # Idempotent: return as-is but still update updated_at? Real APIs often don't. We'll keep unchanged.
        _log(endpoint, "ok", client_id=client_id, meta={"idempotent": True})
        return {"lead": lead}

    if status not in transitions.get(cur, set()):
        _log(endpoint, "error", client_id=client_id, meta={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Requested status transition is not allowed.", from_status=cur, to_status=status)

    lead["status"] = status
    lead["updated_at"] = _iso_now()
    leads[lead_idx] = lead
    _save("leads.json", leads)

    _log(endpoint, "ok", client_id=client_id)
    return {"lead": lead}

def smartlead_bulk_import_leads(campaign_id, leads, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _log(status, client_id=None, meta=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "smartlead_bulk_import_leads",
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").upper()

    # Validate campaign_id (accept sl_cmp_01J... too)
    if not isinstance(campaign_id, str) or not re.match(r"^sl_cmp_01[0-9A-Z]{16,}$", campaign_id):
        _log("error", meta={"field": "campaign_id"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")

    if not isinstance(leads, list) or len(leads) == 0:
        _log("error", meta={"field": "leads"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "leads must be a non-empty array.", field="leads")

    # Load campaign and client
    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    campaign = None
    for c in campaigns:
        if isinstance(c, dict) and c.get("campaign_id") == campaign_id:
            campaign = c
            break
    if campaign is None or campaign.get("status") == "deleted":
        _log("error", meta={"campaign_id": campaign_id}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client_id = campaign.get("client_id")

    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    ok_client = False
    for cl in clients:
        if isinstance(cl, dict) and cl.get("client_id") == client_id and cl.get("status") in ("active", "suspended"):
            ok_client = True
            break
    if not ok_client:
        _log("error", client_id=client_id, meta={"campaign_id": campaign_id}, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible client context for this campaign.", client_id=client_id)

    # Rate limit (bulk endpoint)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in reversed(logs[-5000:]):
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "smartlead_bulk_import_leads":
            continue
        if r.get("client_id") != client_id:
            continue
        ts = r.get("timestamp")
        try:
            dt = datetime.datetime.fromisoformat(str(ts).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt < cutoff:
            break
        recent += 1
        if recent >= 120:
            _log("error", client_id=client_id, meta={"window_s": 60, "limit": 120}, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_s=60, limit=120)

    # Validate lead items and dedupe within request by email lower
    allowed_fields = {"email", "first_name", "last_name", "company", "title", "phone", "linkedin_url", "website", "custom_fields"}
    seen_emails = set()
    cleaned = []
    for i, item in enumerate(leads):
        if not isinstance(item, dict):
            _log("error", client_id=client_id, meta={"field": "leads", "index": i}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each lead must be an object.", field="leads", index=i)
        for k in item.keys():
            if k not in allowed_fields:
                _log("error", client_id=client_id, meta={"field": "leads", "index": i, "unknown_property": k}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown property in leads item.", field="leads", index=i, unknown_property=k)
        em = item.get("email")
        if not isinstance(em, str) or not em.strip() or "@" not in em:
            _log("error", client_id=client_id, meta={"field": "leads.email", "index": i}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "email is required and must be valid.", field="leads", index=i)
        if "custom_fields" in item and item["custom_fields"] is not None and not isinstance(item["custom_fields"], dict):
            _log("error", client_id=client_id, meta={"field": "leads.custom_fields", "index": i}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "custom_fields must be an object when provided.", field="leads", index=i)
        em_norm = em.strip()
        key = em_norm.lower()
        if key in seen_emails:
            # idempotent skip duplicates within same request
            continue
        seen_emails.add(key)
        cleaned.append((em_norm, item))

    leads_store = _load("leads.json")
    if not isinstance(leads_store, list):
        leads_store = []

    created_count = 0
    updated_count = 0
    membership_added = 0
    skipped_count = len(leads) - len(cleaned)

    # index existing leads by email for this client (non-deleted)
    index = {}
    for i, ld in enumerate(leads_store):
        if not isinstance(ld, dict):
            continue
        if ld.get("client_id") != client_id:
            continue
        if ld.get("status") == "deleted":
            continue
        em = ld.get("email")
        if isinstance(em, str):
            index[em.lower()] = i

    for em_norm, item in cleaned:
        key = em_norm.lower()
        li = index.get(key)
        if li is None:
            new_lead = {
                "lead_id": _gen_id("sl_led_"),
                "client_id": client_id,
                "email": em_norm,
                "first_name": item.get("first_name"),
                "last_name": item.get("last_name"),
                "company": item.get("company"),
                "title": item.get("title"),
                "phone": item.get("phone"),
                "linkedin_url": item.get("linkedin_url"),
                "website": item.get("website"),
                "custom_fields": item.get("custom_fields"),
                "status": "active",
                "campaign_memberships": [],
                "created_at": now_iso,
                "updated_at": now_iso
            }
            leads_store.append(new_lead)
            li = len(leads_store) - 1
            index[key] = li
            created_count += 1

        lead_row = leads_store[li]
        changed = False
        # Update provided fields
        for f in ("first_name", "last_name", "company", "title", "phone", "linkedin_url", "website", "custom_fields"):
            if f in item:
                if lead_row.get(f) != item.get(f):
                    lead_row[f] = item.get(f)
                    changed = True

        memberships = lead_row.get("campaign_memberships")
        if not isinstance(memberships, list):
            memberships = []
            lead_row["campaign_memberships"] = memberships

        mem = None
        for m in memberships:
            if isinstance(m, dict) and m.get("campaign_id") == campaign_id:
                mem = m
                break
        if mem is None:
            memberships.append({
                "campaign_id": campaign_id,
                "membership_id": _gen_id("sl_mem_"),
                "campaign_lead_status": "queued",
                "added_at": now_iso,
                "last_status_at": now_iso,
                "sequence_position": 0,
                "last_sent_at": None
            })
            membership_added += 1
            changed = True
        else:
            # idempotent: do nothing; keep as-is
            pass

        if changed:
            lead_row["updated_at"] = now_iso
            leads_store[li] = lead_row
            updated_count += (0 if created_count and lead_row.get("created_at") == now_iso else 1)

    _save("leads.json", leads_store)
    _log("ok", client_id=client_id, meta={"campaign_id": campaign_id, "created": created_count, "updated": updated_count, "membership_added": membership_added, "skipped": skipped_count})

    return {
        "campaign_id": campaign_id,
        "client_id": client_id,
        "received": len(leads),
        "deduped": len(cleaned),
        "created": created_count,
        "updated": updated_count,
        "membership_added": membership_added,
        "skipped": skipped_count
    }

def smartlead_delete_lead(lead_id, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    reqlog = _load("request_logs.json")
    usage = _load("usage_counters.json")

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, credential_used=None, client_id=None, meta=None):
        nonlocal reqlog, usage
        ts = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "request_id": "req_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(16)),
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status_s,
            "latency_ms": latency_ms,
            "credential_used": credential_used,
            "client_id": client_id,
            "meta": meta or {}
        })
        key = endpoint
        found = False
        for row in usage:
            if isinstance(row, dict) and row.get("key") == key:
                row["count"] = int(row.get("count", 0)) + 1
                row["updated_at"] = ts
                found = True
                break
        if not found:
            usage.append({"key": key, "count": 1, "updated_at": ts})
        _save("request_logs.json", reqlog)
        _save("usage_counters.json", usage)

    endpoint = "smartlead_delete_lead"

    # Rate limit deletes per client (heuristic from request_logs)
    def _rate_limited(client_id):
        window_s = 60
        limit = 60
        now = datetime.datetime.utcnow()
        cnt = 0
        for r in reqlog[-5000:]:
            try:
                if r.get("endpoint") != endpoint:
                    continue
                if client_id is not None and r.get("client_id") != client_id:
                    continue
                ts = r.get("timestamp")
                if not ts:
                    continue
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                if (now - dt).total_seconds() <= window_s and r.get("status") == "ok":
                    cnt += 1
            except Exception:
                continue
        return cnt >= limit

    if not isinstance(lead_id, str) or not re.match(r"^sl_led_01H[0-9A-Z]{15,}$", lead_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "lead_id is invalid.", field="lead_id")

    lead_rows = _load("leads.json")
    clients = _load("clients.json")

    lead = None
    lead_idx = None
    for i, r in enumerate(lead_rows):
        if isinstance(r, dict) and r.get("lead_id") == lead_id:
            lead = r
            lead_idx = i
            break

    if not lead:
        _log(endpoint, "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Lead not found.")

    client_id = lead.get("client_id")
    client_ok = any(isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") == "active" for c in clients)
    if not client_ok:
        _log(endpoint, "error", client_id=client_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authorized for this lead's client scope.")

    if _rate_limited(client_id):
        _log(endpoint, "error", client_id=client_id, meta={"code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Delete rate limit exceeded for this client.")

    # Business rule: if lead has active associations that must be removed first -> CONFLICT.
    # We'll treat any membership to a non-deleted campaign as an active association preventing hard delete.
    campaigns = _load("campaigns.json")
    camp_by_id = {c.get("campaign_id"): c for c in campaigns if isinstance(c, dict)}

    mems = lead.get("campaign_memberships") or []
    if not isinstance(mems, list):
        _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Lead campaign_memberships is corrupted; cannot delete lead.")

    active_campaign_refs = []
    for m in mems:
        if not isinstance(m, dict):
            _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "Lead campaign_memberships is corrupted; cannot delete lead.")
        cid = m.get("campaign_id")
        if not cid:
            continue
        camp = camp_by_id.get(cid)
        if camp and camp.get("client_id") == client_id and camp.get("status") != "deleted":
            # consider membership removed status as not active association
            if m.get("campaign_lead_status") != "removed":
                active_campaign_refs.append(cid)

    if active_campaign_refs:
        _log(endpoint, "error", client_id=client_id, meta={"code": "CONFLICT", "active_campaign_refs": len(active_campaign_refs)})
        return _err("CONFLICT", "Lead cannot be permanently deleted while it has active campaign memberships. Remove the lead from campaigns first.", campaign_ids=active_campaign_refs)

    # If already deleted status, still requires actual deletion effect; if row exists, hard delete now.
    del lead_rows[lead_idx]
    _save("leads.json", lead_rows)

    _log(endpoint, "ok", client_id=client_id)
    return {"deleted": True, "lead_id": lead_id}

def smartlead_get_campaign_statistics(campaign_id, email_status=None, sent_time_start_date=None, sent_time_end_date=None, email_sequence_number=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_campaign_statistics"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _log(status, client_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string.", field=field)
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string.", field=field)

    def _rate_limit_check(client_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if client_id and r.get("client_id") != client_id:
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp") or r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
            if cnt > 240:
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60)
        return None

    def _get_client_by_campaign(camp_row):
        cid = camp_row.get("client_id")
        clients = _load("clients.json")
        if not isinstance(clients, list):
            clients = []
        for cl in clients:
            if isinstance(cl, dict) and cl.get("client_id") == cid and cl.get("status") in ("active", "suspended"):
                return cl
        return None

    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is required.", field="campaign_id")
    campaign_id = campaign_id.strip()
    if re.match(r"^sl_cmp_[0-9A-Z]{10,}$", campaign_id) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is malformed.", field="campaign_id")

    if email_sequence_number is not None and (not isinstance(email_sequence_number, int) or email_sequence_number < 1):
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "email_sequence_number"})
        return _err("VALIDATION_ERROR", "email_sequence_number must be an integer >= 1.", field="email_sequence_number")

    st_dt, e1 = _parse_dt(sent_time_start_date, "sent_time_start_date")
    if e1:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "sent_time_start_date"})
        return e1
    en_dt, e2 = _parse_dt(sent_time_end_date, "sent_time_end_date")
    if e2:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "sent_time_end_date"})
        return e2
    if st_dt and en_dt and st_dt > en_dt:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "sent_time_start_date"})
        return _err("VALIDATION_ERROR", "sent_time_start_date must be on or before sent_time_end_date.", field="sent_time_start_date")

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = None
    for c in campaigns:
        if isinstance(c, dict) and c.get("campaign_id") == campaign_id:
            camp = c
            break
    if not camp or camp.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND", meta={"campaign_id": campaign_id})
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client = _get_client_by_campaign(camp)
    if not client:
        _log("error", error_code="UNAUTHORIZED", meta={"campaign_id": campaign_id})
        return _err("UNAUTHORIZED", "You do not have access to this campaign.", campaign_id=campaign_id)

    rl = _rate_limit_check(client.get("client_id"))
    if rl:
        _log("error", client_id=client.get("client_id"), error_code="RATE_LIMIT")
        return rl

    rollups = camp.get("analytics_daily_rollups") or []
    if not isinstance(rollups, list):
        rollups = []

    metric_keys = [
        "sent", "delivered", "opened", "clicked", "replied", "bounced", "unsubscribed", "complained",
        "spam", "failed", "unique_opens", "unique_clicks"
    ]
    totals = {k: 0 for k in metric_keys}
    matched_rows = 0
    dates_set = set()

    def _coerce_int(v):
        if isinstance(v, bool) or v is None:
            return 0
        if isinstance(v, int):
            return v
        if isinstance(v, float):
            return int(v)
        if isinstance(v, str):
            try:
                return int(float(v.strip()))
            except Exception:
                return 0
        return 0

    def _rollup_in_window(r):
        # rollups store date (YYYY-MM-DD). Compare to dt window if given.
        dstr = r.get("date")
        if not isinstance(dstr, str):
            return False
        try:
            d = datetime.date.fromisoformat(dstr)
        except Exception:
            return False
        if st_dt:
            if d < st_dt.date():
                return False
        if en_dt:
            if d > en_dt.date():
                return False
        return True

    for r in rollups:
        if not isinstance(r, dict):
            continue
        if email_sequence_number is not None and r.get("sequence_number") not in (email_sequence_number, str(email_sequence_number)):
            continue
        if not _rollup_in_window(r):
            continue
        # email_status is not modeled in rollups; accept filter but only apply if rollup contains a matching field
        if email_status is not None:
            if isinstance(r.get("email_status"), str):
                if r.get("email_status") != email_status:
                    continue
            # else: cannot filter; proceed (real backend would aggregate from emails table; we don't have it)
        matched_rows += 1
        d = r.get("date")
        if isinstance(d, str):
            dates_set.add(d)
        for k in metric_keys:
            totals[k] += _coerce_int(r.get(k))

    resp = {
        "campaign_id": campaign_id,
        "client_id": client.get("client_id"),
        "filters": {
            "email_status": email_status,
            "sent_time_start_date": sent_time_start_date,
            "sent_time_end_date": sent_time_end_date,
            "email_sequence_number": email_sequence_number,
        },
        "summary": totals,
        "meta": {
            "matched_rollup_rows": matched_rows,
            "days_covered": len(dates_set)
        }
    }
    _log("success", client_id=client.get("client_id"), meta={"campaign_id": campaign_id, "matched_rollup_rows": matched_rows})
    return resp

