def smartlead_get_warmup_stats_by_email(email, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_warmup_stats_by_email"
    cred_used = None

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log_call(result_obj, status):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": cred_used,
            "status": status,
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "params": {"email": email}
        })
        _save("request_logs.json", logs)
        return result_obj

    if not isinstance(email, str) or not email.strip():
        return _log_call(_err("VALIDATION_ERROR", "email is required", field="email"), "error")
    email = email.strip()
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email):
        return _log_call(_err("VALIDATION_ERROR", "email is invalid", field="email"), "error")

    # Locate the mailbox inside smart_delivery_tests.sender_accounts. This store doesn't have a dedicated mailbox collection.
    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list):
        tests = []

    found_any = False
    warmup_enabled_any = False
    # Collect per-day metrics from emails artifacts for last 7 days where sender_account email matches.
    now = datetime.datetime.now(datetime.timezone.utc)
    start = (now - datetime.timedelta(days=6)).date()  # inclusive 7-day window by date
    day_buckets = {}
    for i in range(7):
        d = start + datetime.timedelta(days=i)
        day_buckets[d.isoformat()] = {"date": d.isoformat(), "sent": 0, "inbox": 0, "spam": 0, "missing": 0}

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    for t in tests:
        if not isinstance(t, dict) or t.get("status") == "deleted":
            continue
        sender_accounts = t.get("sender_accounts") or []
        if not isinstance(sender_accounts, list):
            sender_accounts = []
        matched_sender = None
        for sa in sender_accounts:
            if isinstance(sa, dict) and isinstance(sa.get("email"), str) and sa.get("email").strip().lower() == email.lower():
                matched_sender = sa
                break
        if not matched_sender:
            continue
        found_any = True
        if matched_sender.get("warmup_enabled") is True:
            warmup_enabled_any = True

        emails = t.get("emails") or []
        if not isinstance(emails, list):
            emails = []

        # Interpret "warmup stats" from placement_folder distribution.
        for em in emails:
            if not isinstance(em, dict):
                continue
            if em.get("sender_account_id") != matched_sender.get("sender_account_id"):
                continue
            dt = _parse_dt(em.get("sent_at"))
            if not dt:
                continue
            d = dt.date().isoformat()
            if d not in day_buckets:
                continue
            day_buckets[d]["sent"] += 1
            folder = em.get("placement_folder")
            if isinstance(folder, str):
                f = folder.lower()
                if "inbox" in f:
                    day_buckets[d]["inbox"] += 1
                elif "spam" in f or "junk" in f:
                    day_buckets[d]["spam"] += 1
                else:
                    day_buckets[d]["missing"] += 1
            else:
                day_buckets[d]["missing"] += 1

    if not found_any:
        return _log_call(_err("NOT_FOUND", "email account not found", email=email), "error")
    if not warmup_enabled_any:
        # mailbox exists but not accessible for warmup reporting in this dataset
        return _log_call(_err("UNAUTHORIZED", "mailbox is not accessible for warmup stats", email=email), "error")

    resp = {
        "email": email,
        "window_days": 7,
        "daily": [day_buckets[k] for k in sorted(day_buckets.keys())],
        "summary": {
            "sent": sum(x["sent"] for x in day_buckets.values()),
            "inbox": sum(x["inbox"] for x in day_buckets.values()),
            "spam": sum(x["spam"] for x in day_buckets.values()),
            "missing": sum(x["missing"] for x in day_buckets.values())
        }
    }
    return _log_call(resp, "success")

