        logs.append({
            "request_id": "sl_req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is required.", field="campaign_id")
    campaign_id = campaign_id.strip()
    if re.match(r"^sl_cmp_[0-9A-Z]{10,}$", campaign_id) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is malformed.", field="campaign_id")

    if not isinstance(start_date, str) or re.match(r"^\d{4}-\d{2}-\d{2}$", start_date) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "start_date"})
        return _err("VALIDATION_ERROR", "start_date must be YYYY-MM-DD.", field="start_date")
    if not isinstance(end_date, str) or re.match(r"^\d{4}-\d{2}-\d{2}$", end_date) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "end_date"})
        return _err("VALIDATION_ERROR", "end_date must be YYYY-MM-DD.", field="end_date")

    try:
        sd = datetime.date.fromisoformat(start_date)
    except ValueError:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "start_date"})
        return _err("VALIDATION_ERROR", "start_date is not a valid date.", field="start_date")
    try:
        ed = datetime.date.fromisoformat(end_date)
    except ValueError:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "end_date"})
        return _err("VALIDATION_ERROR", "end_date is not a valid date.", field="end_date")
    if sd > ed:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "start_date"})
        return _err("VALIDATION_ERROR", "start_date must be on or before end_date.", field="start_date", start_date=start_date, end_date=end_date)

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list): campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("campaign_id") == campaign_id), None)
    if not camp:
        _log("error", error_code="NOT_FOUND", meta={"campaign_id": campaign_id})
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client_id = camp.get("client_id")
    # Ambient auth: pick any active/suspended client that owns the campaign; do not refuse well-formed calls.
    clients = _load("clients.json")
    if not isinstance(clients, list): clients = []
    client = next((cl for cl in clients if isinstance(cl, dict) and cl.get("client_id") == client_id and cl.get("status") in ("active", "suspended")), None)
    if not client:
        _log("error", client_id=client_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to this campaign.", campaign_id=campaign_id)

    rollups = camp.get("analytics_daily_rollups")
    if not isinstance(rollups, list):
        rollups = []

    # Aggregate across rollups within date range, across all sequence_number/mailbox_id.
    totals = {
        "campaign_id": campaign_id,
        "start_date": start_date,
        "end_date": end_date,
        "opens": 0,
        "clicks": 0,
        "replies": 0,
        "bounces": 0,
        "unsubscribes": 0,
        "sent": 0
    }

    def _as_int(v):
        try:
            if v is None: return 0
            if isinstance(v, bool): return int(v)
            if isinstance(v, (int, float)): return int(v)
            if isinstance(v, str) and v.strip() != "": return int(float(v.strip()))
        except Exception:
            return 0
        return 0

    for r in rollups:
        if not isinstance(r, dict):
            continue
        d = r.get("date")
        if not isinstance(d, str) or re.match(r"^\d{4}-\d{2}-\d{2}$", d) is None:
            continue
        try:
            rd = datetime.date.fromisoformat(d)
        except ValueError:
            continue
        if rd < sd or rd > ed:
            continue

        # Accept several possible field names
        totals["opens"] += _as_int(r.get("open_count", r.get("opens")))
        totals["clicks"] += _as_int(r.get("click_count", r.get("clicks")))
        totals["replies"] += _as_int(r.get("reply_count", r.get("replies")))
        totals["bounces"] += _as_int(r.get("bounce_count", r.get("bounces")))
        totals["unsubscribes"] += _as_int(r.get("unsub_count", r.get("unsubscribes")))
        totals["sent"] += _as_int(r.get("sent_count", r.get("sent")))

    _log("ok", client_id=client_id)
    return {"summary": totals}

