    total_leads = 0
    active_leads = 0
    suppressed_leads = 0
    deleted_leads = 0

    for ld in leads:
        if not isinstance(ld, dict):
            continue
        if ld.get("client_id") != client.get("client_id"):
            continue
        lstat = ld.get("status")
        if lstat == "active":
            active_leads += 1
        elif lstat == "suppressed":
