            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _get_client_by_campaign(camp_row):
        cid = camp_row.get("client_id")
        clients = _load("clients.json")
        if not isinstance(clients, list):
            clients = []
        for cl in clients:
            if isinstance(cl, dict) and cl.get("client_id") == cid and cl.get("status") in ("active", "suspended"):
                return cl
        return None

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").upper()

    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is required.", field="campaign_id")
    campaign_id = campaign_id.strip()
    if re.match(r"^sl_cmp_[0-9A-Z]{10,}$", campaign_id) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is malformed.", field="campaign_id")

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = None
    idx = None
    for i, c in enumerate(campaigns):
        if isinstance(c, dict) and c.get("campaign_id") == campaign_id:
            camp = c
            idx = i
            break
    if not camp or camp.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND", meta={"campaign_id": campaign_id})
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client = _get_client_by_campaign(camp)
    if not client:
        _log("error", error_code="UNAUTHORIZED", meta={"campaign_id": campaign_id})
        return _err("UNAUTHORIZED", "You do not have access to this campaign.", campaign_id=campaign_id)

    # Build CSV from leads joined via campaign_memberships
    leads = _load("leads.json")
    if not isinstance(leads, list):
        leads = []

    out = io.StringIO()
    writer = csv.writer(out)
    header = ["lead_id", "email", "first_name", "last_name", "company", "title", "phone", "linkedin_url", "website", "lead_status", "campaign_lead_status", "added_at", "sequence_position", "last_sent_at"]
    writer.writerow(header)

    row_count = 0
    for ld in leads:
        if not isinstance(ld, dict):
            continue
        if ld.get("client_id") != client.get("client_id"):
            continue
        memberships = ld.get("campaign_memberships") or []
        if not isinstance(memberships, list):
            continue
        mem = None
        for m in memberships:
            if isinstance(m, dict) and m.get("campaign_id") == campaign_id:
                mem = m
                break
        if not mem:
            continue
        writer.writerow([
            ld.get("lead_id"),
            ld.get("email"),
            ld.get("first_name"),
            ld.get("last_name"),
            ld.get("company"),
            ld.get("title"),
            ld.get("phone"),
            ld.get("linkedin_url"),
            ld.get("website"),
            ld.get("status"),
            mem.get("campaign_lead_status"),
            mem.get("added_at"),
            mem.get("sequence_position"),
            mem.get("last_sent_at"),
        ])
        row_count += 1

    csv_data = out.getvalue()

    # Record download event
    download_id = _gen_id("sl_dwn_")
    downloads = camp.get("downloads")
    if downloads is None or not isinstance(downloads, list):
        downloads = []
    downloads.append({
        "download_id": download_id,
        "requested_at": now_iso,
        "requested_by": None,
        "format": "csv",
        "filters": {"campaign_id": campaign_id},
        "row_count": row_count
    })
    camp["downloads"] = downloads
    camp["updated_at"] = now_iso
    campaigns[idx] = camp
    _save("campaigns.json", campaigns)

    resp = {
        "campaign_id": campaign_id,
        "client_id": client.get("client_id"),
        "download": {
            "download_id": download_id,
            "format": "csv",
            "requested_at": now_iso,
            "row_count": row_count,
        },
        "data": {
            "content_type": "text/csv",
            "filename": f"{campaign_id}_export.csv",
            "csv": csv_data
        }
    }
    _log("success", client_id=client.get("client_id"), meta={"campaign_id": campaign_id, "download_id": download_id, "row_count": row_count})
    return resp

def smartlead_view_download_statistics(campaign_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if os.path.exists(path):
            return
        try:
            _save("request_logs.json", [])
        except Exception:
            pass

    def _log(endpoint, status, client_id=None, credential=None, meta=None, started=None):
        try:
            _ensure_request_log()
            logs = _load("request_logs.json")
            if started is None:
                started = time.time()
            latency_ms = int((time.time() - started) * 1000)
            row = {
                "request_id": "sl_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "status": status,
                "client_id": client_id,
                "credential": credential,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    started = time.time()
    endpoint = "smartlead_view_download_statistics"

    # Validate
    if not isinstance(campaign_id, str) or not re.match(r"^sl_cmp_[0-9A-Z]{18,}$", campaign_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "campaign_id is malformed.", field="campaign_id")

    campaigns = _load("campaigns.json")
    campaign = next((c for c in campaigns if c.get("campaign_id") == campaign_id), None)
    if not campaign or campaign.get("status") == "deleted":
        _log(endpoint, "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    client_id = campaign.get("client_id")
    clients = _load("clients.json")
    client = next((cl for cl in clients if cl.get("client_id") == client_id and cl.get("status") == "active"), None)
    if client is None:
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "You don’t have access to this campaign’s analytics.", campaign_id=campaign_id)

    downloads = campaign.get("downloads") or []
    total_downloads = len(downloads)

    # Aggregate formats and recency
    formats = {}
    rows_total = 0
    last_requested_at = None
    last_requested_by = None
    last_download_id = None
    last_filters = None
    for d in downloads:
        fmt = d.get("format") or "unknown"
        formats[fmt] = formats.get(fmt, 0) + 1
        rc = d.get("row_count")
        if isinstance(rc, int) and rc >= 0:
            rows_total += rc
        ra = _parse_iso(d.get("requested_at"))
        if ra is not None and (last_requested_at is None or ra > last_requested_at):
            last_requested_at = ra
            last_requested_by = d.get("requested_by")
            last_download_id = d.get("download_id")
            last_filters = d.get("filters")

    summary = {
        "campaign_id": campaign_id,
        "client_id": client_id,
        "download_count": total_downloads,
        "formats": [{"format": k, "count": v} for k, v in sorted(formats.items(), key=lambda x: (-x[1], x[0]))],
        "total_rows_exported": rows_total,
        "last_download": None if last_requested_at is None else {
            "download_id": last_download_id,
            "requested_at": (last_requested_at.replace(microsecond=0).isoformat() + "Z"),
            "requested_by": last_requested_by,
            "filters": last_filters,
        },
        "first_download_at": None,
        "last_30_days": {"download_count": 0, "total_rows_exported": 0},
    }

    # First download + last 30 days window
    if downloads:
        earliest = None
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(days=30)
        w_count = 0
        w_rows = 0
        for d in downloads:
            ra = _parse_iso(d.get("requested_at"))
            if ra is None:
                continue
            if earliest is None or ra < earliest:
                earliest = ra
            if ra >= window_start:
                w_count += 1
                rc = d.get("row_count")
                if isinstance(rc, int) and rc >= 0:
                    w_rows += rc
        if earliest is not None:
            summary["first_download_at"] = earliest.replace(microsecond=0).isoformat() + "Z"
        summary["last_30_days"] = {"download_count": w_count, "total_rows_exported": w_rows}

    _log(endpoint, "ok", client_id=client_id, meta={"campaign_id": campaign_id})
    return {"data": summary}

def smartlead_get_region_wise_providers(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if os.path.exists(path):
            return
        try:
            _save("request_logs.json", [])
        except Exception:
            pass

    def _log(endpoint, status, client_id=None, credential=None, meta=None, started=None):
        try:
            _ensure_request_log()
            logs = _load("request_logs.json")
            if started is None:
                started = time.time()
            latency_ms = int((time.time() - started) * 1000)
            row = {
                "request_id": "sl_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "status": status,
                "client_id": client_id,
                "credential": credential,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    def _rate_limit_check(endpoint, started):
        # Simple per-endpoint rolling window: 120 requests/minute across datastore (ambient auth).
        try:
            _ensure_request_log()
            logs = _load("request_logs.json")
            now = datetime.datetime.utcnow()
            window_start = now - datetime.timedelta(seconds=60)
            count = 0
            for r in reversed(logs[-5000:]):
                if r.get("endpoint") != endpoint:
                    continue
                ts = r.get("timestamp")
                try:
                    if ts and ts.endswith("Z"):
                        dt = datetime.datetime.fromisoformat(ts[:-1])
                    else:
                        dt = datetime.datetime.fromisoformat(ts)
                except Exception:
                    continue
                if dt < window_start:
                    break
                count += 1
            if count >= 120:
                _log(endpoint, "error", meta={"code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            return None
        except Exception:
            return None

    started = time.time()
    endpoint = "smartlead_get_region_wise_providers"

    rl = _rate_limit_check(endpoint, started)
    if rl:
        return rl

    # Ambient auth: must have at least one active client in store to be considered authorized.
    clients = _load("clients.json")
    active_clients = [c for c in clients if c.get("status") == "active"]
    if not active_clients:
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Your API key cannot access provider catalogs for your workspace.")

    # Prefer dedicated vendor catalog records
    recs = _load("integrations_and_procurement.json")
    vendors = [
        r for r in recs
        if r.get("record_type") == "domain_vendor" and r.get("status") == "active" and isinstance(r.get("payload"), dict)
    ]

    provider_rows = []
    for v in vendors:
        payload = v.get("payload") or {}
        vendor_id = payload.get("vendor_id")
        name = payload.get("name")
        regions = payload.get("regions") or []
        if not vendor_id or not isinstance(regions, list):
            continue
        for reg in regions:
            if not isinstance(reg, dict):
                continue
            # expected shape: {region, country, providers:[{provider_id, provider_name}]}
            region_name = reg.get("region") or reg.get("region_name") or "unknown"
            country = reg.get("country") or reg.get("country_code") or None
            providers_list = reg.get("providers") or reg.get("provider_ids") or []
            if isinstance(providers_list, list):
                for p in providers_list:
                    if isinstance(p, dict):
                        pid = p.get("provider_id")
                        pname = p.get("provider_name") or p.get("name")
                    else:
                        pid = p
                        pname = None
                    if not isinstance(pid, str) or not pid:
                        continue
                    provider_rows.append({
                        "provider_id": pid,
                        "provider_name": pname,
                        "region": region_name,
                        "country": country,
                        "vendor_id": vendor_id,
                        "vendor_name": name,
                    })

    # Fallback: cached provider catalog inside smart_delivery_tests.aggregate_reports.provider_catalog
    if not provider_rows:
        tests = _load("smart_delivery_tests.json")
        for t in tests:
            agg = t.get("aggregate_reports")
            if not isinstance(agg, dict):
                continue
            catalog = agg.get("provider_catalog")
            if not isinstance(catalog, list):
                continue
            for p in catalog:
                if not isinstance(p, dict):
                    continue
                pid = p.get("provider_id")
                if not isinstance(pid, str) or not pid:
                    continue
                provider_rows.append({
                    "provider_id": pid,
                    "provider_name": p.get("provider_name"),
                    "region": p.get("region") or p.get("region_name") or "unknown",
                    "country": p.get("country") or p.get("country_code"),
                    "vendor_id": p.get("vendor_id"),
                    "vendor_name": p.get("vendor_name"),
                })
        # If still empty, no upstream refresh available offline: return empty list (authorized).
        # (A read with no matches returns empty result set.)

    # Group by region -> country
    regions = {}
    for p in provider_rows:
        region = p.get("region") or "unknown"
        country = p.get("country") or "unknown"
        regions.setdefault(region, {}).setdefault(country, {})
        pid = p["provider_id"]
        if pid not in regions[region][country]:
            regions[region][country][pid] = {
                "provider_id": pid,
                "provider_name": p.get("provider_name"),
                "region": region if region != "unknown" else None,
                "country": None if country == "unknown" else country,
            }

    out = []
    for region, countries in sorted(regions.items(), key=lambda x: x[0]):
        c_out = []
        for country, providers_map in sorted(countries.items(), key=lambda x: x[0]):
            c_out.append({
                "country": None if country == "unknown" else country,
                "providers": sorted(list(providers_map.values()), key=lambda x: x["provider_id"]),
            })
        out.append({"region": None if region == "unknown" else region, "countries": c_out})

    _log(endpoint, "ok", meta={"provider_count": len(provider_rows)})
    return {"data": {"regions": out, "total_providers": len({p["provider_id"] for p in provider_rows})}}

def smartlead_create_manual_placement_test(client_id, folder_id, name, providers, sender_accounts, receiver_mailboxes, emails, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _log(status, client_id=None, meta=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "smartlead_create_manual_placement_test",
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").upper()

    # Validate formats (relax to match datastore 01J... too)
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-Z]{18,}$", client_id):
        _log("error", meta={"field": "client_id"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "client_id is malformed.", field="client_id")
    if not isinstance(folder_id, str) or not re.match(r"^sl_sdf_[0-9A-Z]{18,}$", folder_id):
        _log("error", client_id=client_id, meta={"field": "folder_id"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "folder_id is malformed.", field="folder_id")
    if not isinstance(name, str) or not name.strip():
        _log("error", client_id=client_id, meta={"field": "name"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required.", field="name")
    if not isinstance(providers, list) or len(providers) == 0 or not all(isinstance(p, str) and p for p in providers):
        _log("error", client_id=client_id, meta={"field": "providers"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "providers must be a non-empty array of strings.", field="providers")
    if not isinstance(sender_accounts, list) or len(sender_accounts) == 0:
        _log("error", client_id=client_id, meta={"field": "sender_accounts"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sender_accounts must be a non-empty array.", field="sender_accounts")
    if not isinstance(receiver_mailboxes, list) or len(receiver_mailboxes) == 0:
        _log("error", client_id=client_id, meta={"field": "receiver_mailboxes"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "receiver_mailboxes must be a non-empty array.", field="receiver_mailboxes")
    if not isinstance(emails, list) or len(emails) == 0:
        _log("error", client_id=client_id, meta={"field": "emails"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "emails must be a non-empty array.", field="emails")

    # Check client exists and is accessible
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    cl = None
    for r in clients:
        if isinstance(r, dict) and r.get("client_id") == client_id and r.get("status") in ("active", "suspended"):
            cl = r
            break
    if cl is None:
        _log("error", client_id=client_id, meta={"field": "client_id"}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Client not found.", client_id=client_id)

    # Check folder belongs to client
    folders = _load("smart_delivery_folders.json")
    if not isinstance(folders, list):
        folders = []
    folder = None
    for f in folders:
        if isinstance(f, dict) and f.get("folder_id") == folder_id:
            folder = f
            break
    if folder is None or folder.get("status") == "deleted":
        _log("error", client_id=client_id, meta={"folder_id": folder_id}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Folder not found.", folder_id=folder_id)
    if folder.get("client_id") != client_id:
        _log("error", client_id=client_id, meta={"folder_id": folder_id, "rule": "cross-client"}, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Cross-client access is rejected.", rule="All reads and writes are scoped to a client_id; cross-client access is rejected.", folder_id=folder_id)

    # Rate limit per client
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in reversed(logs[-5000:]):
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "smartlead_create_manual_placement_test":
            continue
        if r.get("client_id") != client_id:
            continue
        ts = r.get("timestamp")
        try:
            dt = datetime.datetime.fromisoformat(str(ts).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt < cutoff:
            break
        recent += 1
        if recent >= 60:
            _log("error", client_id=client_id, meta={"window_s": 60, "limit": 60}, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_s=60, limit=60)

    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list):
        tests = []

    # Build provider objects: try to resolve vendor catalog; otherwise store ids only.
    iap = _load("integrations_and_procurement.json")
    if not isinstance(iap, list):
        iap = []
    provider_catalog = {}
    for rec in iap:
        if not isinstance(rec, dict):
            continue
        if rec.get("record_type") != "domain_vendor":
            continue
        if rec.get("status") != "active":
            continue
        payload = rec.get("payload")
        if not isinstance(payload, dict):
            continue
        regions = payload.get("regions")
        if isinstance(regions, list):
            for rg in regions:
                if isinstance(rg, dict):
                    pid = rg.get("provider_id") or rg.get("id")
                    if isinstance(pid, str) and pid:
                        provider_catalog[pid] = {
                            "provider_id": pid,
                            "region": rg.get("region"),
                            "country": rg.get("country"),
                            "provider_name": rg.get("provider_name") or rg.get("name")
                        }

    providers_obj = []
    for pid in providers:
        if pid in provider_catalog:
            providers_obj.append(provider_catalog[pid])
        else:
            providers_obj.append({"provider_id": pid, "region": None, "country": None, "provider_name": None})

    test_row = {
        "test_id": _gen_id("sl_sdt_"),
        "client_id": client_id,
        "folder_id": folder_id,
        "test_type": "manual",
        "name": name.strip(),
        "status": "running",
