    if not isinstance(providers, list) or len(providers) == 0 or not all(isinstance(p, str) and p for p in providers):
        _log("error", client_id=client_id, meta={"field": "providers"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "providers must be a non-empty array of strings.", field="providers")
