        "sender_accounts": sender_accounts,
        "receiver_mailboxes": receiver_mailboxes,
        "runs": [],
        "emails": emails,
        "aggregate_reports": {},
        "created_at": now_iso,
        "updated_at": now_iso
    }
    tests.append(test_row)
    _save("smart_delivery_tests.json", tests)
    _log("ok", client_id=client_id, meta={"test_id": test_row["test_id"], "folder_id": folder_id})
