def smartlead_delete_smart_delivery_tests(test_ids, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _log(status, client_id=None, meta=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "smartlead_delete_smart_delivery_tests",
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate input list
    if not isinstance(test_ids, list) or len(test_ids) < 1:
        _log("error", meta={"field": "test_ids"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "test_ids must be a non-empty array", field="test_ids")
    if len(set(test_ids)) != len(test_ids):
        _log("error", meta={"field": "test_ids"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "test_ids contains duplicates", field="test_ids")
    for x in test_ids:
        if not isinstance(x, str) or not re.match(r"^sl_sdt_01[0-9A-Z]{16,}$", x):
            _log("error", meta={"field": "test_ids"}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "One or more test_ids are invalid", field="test_ids")

    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list):
        tests = []

    # Build map for lookup and determine client context(s)
    id_to_idx = {}
    for i, t in enumerate(tests):
        if isinstance(t, dict) and t.get("test_id"):
            id_to_idx[t["test_id"]] = i

    # Ensure all exist; also determine per-test client
    missing = [tid for tid in test_ids if tid not in id_to_idx]
    if missing:
        _log("error", meta={"missing": missing}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "One or more test_ids do not exist.", missing=missing)

    # Rate limit (per client aggregate; use first client's id as reference but enforce global ceiling too)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = now_dt - datetime.timedelta(hours=1)
    recent = 0
    for r in reversed(logs[-10000:]):
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "smartlead_delete_smart_delivery_tests":
            continue
        ts = r.get("timestamp")
        try:
            dt = datetime.datetime.fromisoformat(str(ts).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt < cutoff:
            break
        recent += 1
        if recent >= 1200:
            _log("error", meta={"window_s": 3600, "limit": 1200}, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded", window_s=3600, limit=1200)

    deleted = []
    already_deleted = []
    for tid in test_ids:
        t = tests[id_to_idx[tid]]
        cid = t.get("client_id")
        if t.get("status") == "deleted":
            already_deleted.append(tid)
            continue
        # lifecycle transition to deleted allowed from any non-deleted per schema? transitions allow stopped->deleted, scheduled->deleted, draft->deleted; running cannot go to deleted directly per schema.
        if t.get("status") == "running":
            _log("error", client_id=cid, meta={"test_id": tid, "from": "running", "to": "deleted"}, error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "cannot transition test from running to deleted", test_id=tid)
        t["status"] = "deleted"
        t["updated_at"] = now_iso
        deleted.append(tid)

    if not deleted and not already_deleted:
        _log("error", meta={"test_ids": test_ids}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No tests were deleted.", test_ids=test_ids)

    _save("smart_delivery_tests.json", tests)
    _log("ok", meta={"deleted": deleted, "already_deleted": already_deleted})

    return {"deleted": deleted, "already_deleted": already_deleted, "requested": test_ids}

def smartlead_stop_automated_test(test_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list): reqlogs = []
    def _log(status, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        reqlogs.append({
            "request_id": f"sl_req_{int(time.time()*1000)}",
            "endpoint": "smartlead_stop_automated_test",
            "status": status,
            "timestamp": now,
            "latency_ms": latency_ms,
            "credential_used": None,
            "meta": meta or {}
        })
        _save(reqlog_name, reqlogs)

    one_hour_ago = (datetime.datetime.utcnow() - datetime.timedelta(hours=1)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in reqlogs[-5000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str) and ts >= one_hour_ago:
            recent += 1
    if recent >= 1200:
        _log("RATE_LIMIT", meta={"window": "1h", "limit": 1200})
        return _err("RATE_LIMIT", "Rate limit exceeded", window="1h", limit=1200)

    if not isinstance(test_id, str) or not re.match(r"^sl_sdt_01H[0-9A-Z]{15,}$", test_id):
        _log("VALIDATION_ERROR", meta={"field": "test_id"})
        return _err("VALIDATION_ERROR", "test_id is invalid", field="test_id")

    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list): tests = []

    test = next((x for x in tests if isinstance(x, dict) and x.get("test_id") == test_id), None)
    if not test or test.get("status") == "deleted":
        _log("NOT_FOUND", meta={"test_id": test_id})
        return _err("NOT_FOUND", "Test not found")

    client_id = test.get("client_id")
    clients = _load("clients.json")
    if not isinstance(clients, list): clients = []
    client = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id), None)
    if not client or client.get("status") == "deleted":
        _log("NOT_FOUND", meta={"test_id": test_id})
        return _err("NOT_FOUND", "Test not found")

    if test.get("test_type") != "automated":
        _log("CONFLICT", meta={"test_id": test_id, "reason": "not_automated"})
        return _err("CONFLICT", "Test is not an automated test")

    # Allowed transitions for stop: scheduled/running -> stopped
    st = test.get("status")
    if st not in ("scheduled", "running"):
        _log("CONFLICT", meta={"test_id": test_id, "status": st})
        return _err("CONFLICT", f"Test in state '{st}' cannot be stopped")

    # lifecycle enforcement: scheduled->stopped allowed, running->stopped allowed
    test["status"] = "stopped"
    test["updated_at"] = now
    # business rule: set schedule.next_run_at = null
    sched = test.get("schedule")
    if isinstance(sched, dict):
        sched["next_run_at"] = None
    else:
        # automated implies schedule present; keep consistent
        test["schedule"] = {"next_run_at": None}

    _save("smart_delivery_tests.json", tests)
    _log("OK", meta={"test_id": test_id, "client_id": client_id})
    return {"data": test}

