        if not isinstance(status, str) or status not in ("draft", "scheduled", "running", "stopped", "completed", "deleted"):
            _log("VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if folder_id is not None:
        if not isinstance(folder_id, str) or not re.match(r"^sl_sdf_01H[0-9A-Z]{15,}$", folder_id):
            _log("VALIDATION_ERROR", meta={"field": "folder_id"})
            return _err("VALIDATION_ERROR", "Invalid folder_id", field="folder_id")
    if client_id is not None:
        if not isinstance(client_id, str) or not re.match(r"^sl_cli_01H[0-9A-Z]{15,}$", client_id):
            _log("VALIDATION_ERROR", meta={"field": "client_id"})
            return _err("VALIDATION_ERROR", "Invalid client_id", field="client_id")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    if sort_by is None:
        sort_by = "created_at"
    if sort_order is None:
        sort_order = "desc"
    if sort_by not in ("created_at", "updated_at", "name", "status"):
        _log("VALIDATION_ERROR", meta={"field": "sort_by"})
        return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
    if sort_order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", meta={"field": "sort_order"})
        return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

    # Decode cursor if present
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("VALIDATION_ERROR", meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("off:"):
                _log("VALIDATION_ERROR", meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _log("VALIDATION_ERROR", meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list): tests = []
    clients = _load("clients.json")
    if not isinstance(clients, list): clients = []

    # Determine accessible clients:
    # - If client_id provided: must exist and not deleted; scope to it.
    # - If not: scope to all non-deleted clients (ambient auth assumed to allow at least one).
    allowed_client_ids = set()
    if client_id is not None:
        c = next((x for x in clients if isinstance(x, dict) and x.get("client_id") == client_id), None)
        if not c or c.get("status") == "deleted":
            # empty result set, not error for list
            allowed_client_ids = set()
        else:
            allowed_client_ids = {client_id}
    else:
        for c in clients:
            if isinstance(c, dict) and isinstance(c.get("client_id"), str) and c.get("status") != "deleted":
                allowed_client_ids.add(c["client_id"])

    # Folder filter: if provided, ensure folder exists and is owned by client scope if any
    if folder_id is not None:
        folders = _load("smart_delivery_folders.json")
        if not isinstance(folders, list): folders = []
        folder = next((f for f in folders if isinstance(f, dict) and f.get("folder_id") == folder_id), None)
        if folder is None:
            # empty list
            allowed_for_folder = set()
        else:
            fid_client = folder.get("client_id")
            if client_id is not None and fid_client != client_id:
                # cross-client access rejected -> NOT_FOUND-esque for list? return empty to avoid leaking.
                allowed_for_folder = set()
            else:
                allowed_for_folder = {fid_client} if isinstance(fid_client, str) else set()
        allowed_client_ids = allowed_client_ids.intersection(allowed_for_folder) if allowed_client_ids else allowed_for_folder

    # Apply filters
    rows = []
    for t in tests:
        if not isinstance(t, dict):
            continue
        cid = t.get("client_id")
        if not isinstance(cid, str) or (allowed_client_ids and cid not in allowed_client_ids):
            continue
        if test_type is not None and t.get("test_type") != test_type:
            continue
        if status is not None:
            if t.get("status") != status:
                continue
        else:
            # deleted excluded by default
            if t.get("status") == "deleted":
                continue
        if folder_id is not None and t.get("folder_id") != folder_id:
            continue
        rows.append(t)

    def _key(v):
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return v
        return str(v).lower()

    reverse = (sort_order == "desc")
    # stable sort with tie-breaker on test_id
    rows.sort(key=lambda r: (_key(r.get(sort_by)), _key(r.get("test_id"))), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{offset+limit}".encode("utf-8")).decode("utf-8")

    _log("OK", meta={"client_id": client_id, "returned": len(page), "total": total, "offset": offset})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

def smartlead_get_provider_wise_report(test_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage/audit log (best-effort; schema may not have a dedicated collection)
    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "smartlead_get_provider_wise_report",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(test_id, str):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "test_id must be a string")
    if not re.match(r"^sl_sdt_01H[0-9A-Z]{15,}$", test_id):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "test_id does not match required format", field="test_id")

    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list):
        tests = []

    test = next((r for r in tests if isinstance(r, dict) and r.get("test_id") == test_id and r.get("status") != "deleted"), None)
    if not test:
        _log("error", {"code": "NOT_FOUND", "test_id": test_id})
        return _err("NOT_FOUND", "Smart Delivery test not found", test_id=test_id)

    # Report availability rule: needs results; conflict for draft/scheduled/running or otherwise no artifacts
    status = test.get("status")
    emails = test.get("emails") if isinstance(test.get("emails"), list) else []
    runs = test.get("runs") if isinstance(test.get("runs"), list) else []
    if status in ("draft", "scheduled", "running") or (len(emails) == 0 and len(runs) == 0):
        _log("error", {"code": "CONFLICT", "status": status})
        return _err("CONFLICT", "Report is not available yet for this test", test_status=status)

    # Prefer precomputed aggregates if present
    agg = test.get("aggregate_reports") if isinstance(test.get("aggregate_reports"), dict) else {}
    provider_report = agg.get("provider_wise") if isinstance(agg.get("provider_wise"), (list, dict)) else None
    if provider_report is not None:
        _log("ok", {"source": "aggregate_reports"})
        return {
            "test_id": test_id,
            "report_type": "provider_wise",
            "source": "aggregate_reports",
            "generated_at": test.get("updated_at") or test.get("created_at") or now,
            "data": provider_report
        }

    # Compute from emails
    def _placement_bucket(v):
        if not isinstance(v, str):
            return "unknown"
        s = v.strip().lower()
        if s in ("inbox", "primary", "promotions", "social", "updates", "forums"):
            return "inbox"
        if "spam" in s or "junk" in s:
            return "spam"
        if "missing" in s or "not_found" in s or "not found" in s:
            return "missing"
        return s or "unknown"

    # Map receiver mailbox -> provider_id/provider_name if possible
    providers = test.get("providers") if isinstance(test.get("providers"), list) else []
    provider_by_id = {}
    for p in providers:
        if isinstance(p, dict) and p.get("provider_id"):
            provider_by_id[p.get("provider_id")] = p

    receiver_mailboxes = test.get("receiver_mailboxes") if isinstance(test.get("receiver_mailboxes"), list) else []
    rmbx_by_id = {}
    for m in receiver_mailboxes:
        if isinstance(m, dict) and m.get("mailbox_id"):
            rmbx_by_id[m.get("mailbox_id")] = m

    buckets = {}
    total = 0
    for e in emails:
        if not isinstance(e, dict):
            continue
        total += 1
        rmbx = rmbx_by_id.get(e.get("receiver_mailbox_id"), {})
        provider_id = rmbx.get("provider_id") or e.get("provider_id")
        p = provider_by_id.get(provider_id, {}) if provider_id else {}
        provider_name = (p.get("provider_name") or rmbx.get("provider_name") or e.get("provider_name") or "unknown")
        key = provider_id or provider_name
        if key not in buckets:
            buckets[key] = {
                "provider_id": provider_id,
                "provider_name": provider_name,
                "delivered": 0,
                "inbox": 0,
                "spam": 0,
                "missing": 0,
                "unknown": 0,
                "avg_spam_score": None,
                "_spam_score_sum": 0.0,
                "_spam_score_n": 0
            }
        b = buckets[key]
        b["delivered"] += 1
        placement = _placement_bucket(e.get("placement_folder"))
        if placement in ("inbox", "spam", "missing", "unknown"):
            b[placement] += 1
        else:
            b["unknown"] += 1

        ss = e.get("spam_score")
        if isinstance(ss, (int, float)):
            # enforce schema: 0..10; ignore out-of-range instead of failing reads
            if 0 <= float(ss) <= 10:
                b["_spam_score_sum"] += float(ss)
                b["_spam_score_n"] += 1

    rows = list(buckets.values())
    for r in rows:
        n = r.pop("_spam_score_n", 0)
        s = r.pop("_spam_score_sum", 0.0)
        r["avg_spam_score"] = (round(s / n, 4) if n else None)
        r["inbox_rate"] = (round(r["inbox"] / r["delivered"], 6) if r["delivered"] else 0.0)
        r["spam_rate"] = (round(r["spam"] / r["delivered"], 6) if r["delivered"] else 0.0)

    # sort by delivered desc then provider_name
    rows.sort(key=lambda x: (-(x.get("delivered") or 0), (x.get("provider_name") or "").lower()))

    _log("ok", {"source": "computed", "emails": len(emails)})
    return {
        "test_id": test_id,
        "report_type": "provider_wise",
        "source": "computed_from_emails",
        "generated_at": now,
        "summary": {
            "emails_count": total,
            "providers_count": len(rows)
        },
        "data": rows
    }

def smartlead_get_group_wise_report(test_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_group_wise_report"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, client_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": "sl_req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(test_id, str) or not test_id.strip():
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "test_id"})
        return _err("VALIDATION_ERROR", "test_id must be a string.", field="test_id")
    test_id = test_id.strip()
    # Relaxed acceptance: store contains sl_sdt_01J... ids; allow any reasonable sl_sdt_...
    if re.match(r"^sl_sdt_[0-9A-Z]{10,}$", test_id) is None:
        _log("error", error_code="VALIDATION_ERROR", meta={"field": "test_id"})
        return _err("VALIDATION_ERROR", "test_id does not match required format.", field="test_id")

    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list): tests = []
    test = next((r for r in tests if isinstance(r, dict) and r.get("test_id") == test_id), None)
    if not test or test.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND", meta={"test_id": test_id})
        return _err("NOT_FOUND", "Smart Delivery test not found.", test_id=test_id)

    client_id = test.get("client_id")
    clients = _load("clients.json")
    if not isinstance(clients, list): clients = []
    client = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") in ("active", "suspended")), None)
    if not client:
        _log("error", client_id=client_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to this test.", test_id=test_id)

    emails = test.get("emails") if isinstance(test.get("emails"), list) else []
    runs = test.get("runs") if isinstance(test.get("runs"), list) else []

    if (not emails) and (not runs):
        _log("error", client_id=client_id, error_code="CONFLICT", meta={"reason": "no_results"})
        return _err("CONFLICT", "Report is not available yet for this test.", test_id=test_id)

    agg = test.get("aggregate_reports") if isinstance(test.get("aggregate_reports"), dict) else {}
    group = agg.get("group_wise_report") or agg.get("group_wise") or agg.get("group_report")

    if isinstance(group, list):
        _log("ok", client_id=client_id)
        return {"test_id": test_id, "group_wise_report": group, "source": "aggregate_reports"}
    if isinstance(group, dict):
        _log("ok", client_id=client_id)
        return {"test_id": test_id, "group_wise_report": group, "source": "aggregate_reports"}

    # Build from emails if aggregate missing.
    buckets = {}
    for e in emails:
        if not isinstance(e, dict):
            continue
        region = e.get("region") or e.get("receiver_region")
        country = e.get("country") or e.get("receiver_country")
        provider = e.get("provider_name") or e.get("provider") or e.get("receiver_provider")
        placement = e.get("placement_folder") or e.get("placement") or "unknown"
        key = (str(region or "unknown"), str(country or "unknown"), str(provider or "unknown"))
        b = buckets.get(key)
        if b is None:
            b = {
                "region": key[0],
                "country": key[1],
                "provider_name": key[2],
                "emails": 0,
                "inbox": 0,
                "spam": 0,
                "other": 0
            }
            buckets[key] = b
        b["emails"] += 1
        pl = str(placement).lower()
        if "inbox" in pl:
            b["inbox"] += 1
        elif "spam" in pl or "junk" in pl:
            b["spam"] += 1
        else:
            b["other"] += 1

    report = list(buckets.values())
    _log("ok", client_id=client_id)
    return {"test_id": test_id, "group_wise_report": report, "source": "emails"}

