def smartlead_get_spam_filter_details(test_id, sender_email=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "smartlead_get_spam_filter_details",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(test_id, str):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "test_id must be a string")
    if not re.match(r"^sl_sdt_01H[0-9A-Z]{15,}$", test_id):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "test_id does not match required format", field="test_id")

    sender_email_norm = None
    if sender_email is not None:
        if not isinstance(sender_email, str) or not sender_email.strip():
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "sender_email must be a non-empty string when provided", field="sender_email")
        sender_email_norm = sender_email.strip().lower()
        # basic email validation
        if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", sender_email_norm):
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "sender_email is malformed", field="sender_email")

    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list):
        tests = []

    test = next((r for r in tests if isinstance(r, dict) and r.get("test_id") == test_id and r.get("status") != "deleted"), None)
    if not test:
        _log("error", {"code": "NOT_FOUND", "test_id": test_id})
        return _err("NOT_FOUND", "Smart Delivery test not found", test_id=test_id)

    status = test.get("status")
    emails = test.get("emails") if isinstance(test.get("emails"), list) else []
    runs = test.get("runs") if isinstance(test.get("runs"), list) else []
    if status in ("draft", "scheduled", "running") or (len(emails) == 0 and len(runs) == 0):
        _log("error", {"code": "CONFLICT", "status": status})
        return _err("CONFLICT", "Spam-filter report is not available yet for this test", test_status=status)

    # Filter to sender if requested
    sender_accounts = test.get("sender_accounts") if isinstance(test.get("sender_accounts"), list) else []
    sender_id_set = None
    if sender_email_norm is not None:
        matching = [s for s in sender_accounts if isinstance(s, dict) and isinstance(s.get("email"), str) and s.get("email").strip().lower() == sender_email_norm]
        # If sender email not configured on test, still allow filtering by email artifacts in emails (do not error)
        sender_id_set = set(s.get("sender_account_id") for s in matching if s.get("sender_account_id"))

    filtered = []
    for e in emails:
        if not isinstance(e, dict):
            continue
        if sender_email_norm is not None:
            ok = False
            if sender_id_set and e.get("sender_account_id") in sender_id_set:
                ok = True
            # fallback match by sender_email/from_email stored on email artifact
            se = e.get("sender_email") or e.get("from_email")
            if not ok and isinstance(se, str) and se.strip().lower() == sender_email_norm:
                ok = True
            if not ok:
                continue
        filtered.append(e)

    # If we have no email artifacts after filtering, it's still a normal successful read (empty) only if test has results.
    # But spam-filter details specifically require spam_score/signals; if nothing available at all, conflict.
    has_any_spam_artifacts = any(isinstance(e, dict) and (isinstance(e.get("spam_score"), (int, float)) or e.get("spam_filter") is not None or e.get("spam_signals") is not None) for e in filtered)
    if not has_any_spam_artifacts:
        _log("error", {"code": "CONFLICT", "filtered_emails": len(filtered)})
        return _err("CONFLICT", "Spam-filter details are not available for this test (no spam artifacts yet)")

    # Build response: per email spam score + contributing signals where present
    items = []
    score_sum = 0.0
    score_n = 0
    for e in filtered:
        if not isinstance(e, dict):
            continue
        ss = e.get("spam_score")
        if isinstance(ss, (int, float)) and 0 <= float(ss) <= 10:
            score_sum += float(ss)
            score_n += 1
        items.append({
            "email_id": e.get("email_id"),
            "sender_account_id": e.get("sender_account_id"),
            "sender_email": e.get("sender_email") or e.get("from_email"),
            "receiver_mailbox_id": e.get("receiver_mailbox_id"),
            "sent_at": e.get("sent_at"),
            "placement_folder": e.get("placement_folder"),
            "spam_score": e.get("spam_score"),
            "spam_filter": e.get("spam_filter"),     # optional vendor-specific payload if present
            "spam_signals": e.get("spam_signals"),   # optional contributing signals if present
            "auth_results": e.get("auth_results"),
            "blacklist_hits": e.get("blacklist_hits"),
            "ip": e.get("ip")
        })

    # Sort by sent_at if present else email_id
    def _sort_key(x):
        sa = x.get("sent_at")
        return (sa is None, sa or "", x.get("email_id") or "")
    items.sort(key=_sort_key)

    _log("ok", {"source": "emails", "emails": len(filtered), "filtered_sender": sender_email_norm is not None})
    return {
        "test_id": test_id,
        "report_type": "spam_filter_details",
        "generated_at": now,
        "filters": {"sender_email": sender_email_norm},
        "summary": {
            "emails_count": len(items),
            "avg_spam_score": (round(score_sum / score_n, 4) if score_n else None)
        },
        "data": items
    }

