        emails = test.get("emails") or []
        if not isinstance(emails, list): emails = []
        runs = test.get("runs") or []
        if not isinstance(runs, list): runs = []

        if run_id is not None:
            if not any(isinstance(r, dict) and r.get("run_id") == run_id for r in runs):
                _log("error", client_id=client_id, error_code="NOT_FOUND", meta={"run_id": run_id})
                return _err("NOT_FOUND", "run_id not found in test.", test_id=test_id, run_id=run_id)

        filtered = []
        for e in emails:
            if not isinstance(e, dict):
                continue
            if email_id is not None and e.get("email_id") != email_id:
                continue
            if run_id is not None and e.get("run_id") != run_id:
                continue
            filtered.append(e)

        if email_id is not None and not filtered:
            _log("error", client_id=client_id, error_code="NOT_FOUND", meta={"email_id": email_id})
            return _err("NOT_FOUND", "email_id not found in test.", test_id=test_id, email_id=email_id)

        # Extract DKIM-related fields from email artifacts; tolerate schema variations.
        dkim_rows = []
        for e in filtered:
            auth = e.get("auth_results") if isinstance(e.get("auth_results"), dict) else {}
            dkim = auth.get("dkim")
            row = {
                "test_id": test_id,
                "run_id": e.get("run_id"),
                "email_id": e.get("email_id"),
                "sender_account_id": e.get("sender_account_id"),
                "receiver_mailbox_id": e.get("receiver_mailbox_id"),
                "sent_at": e.get("sent_at"),
                "dkim": dkim if dkim is not None else auth.get("dkim_result") or e.get("dkim") or None,
            }
            # Normalize common shapes
            if isinstance(row["dkim"], str):
                row["dkim"] = {"result": row["dkim"]}
            dkim_rows.append(row)

        # If no emails exist, return empty dataset (valid read)
        resp = {
            "test_id": test_id,
            "scope": {"run_id": run_id, "email_id": email_id},
            "results": dkim_rows,
            "total": len(dkim_rows),
        }
        _log("success", client_id=client_id)
        return resp
    except Exception:
        _log("error", error_code="VALIDATION_ERROR", meta={"unhandled": True})
        return _err("VALIDATION_ERROR", "Request could not be processed due to an unexpected condition.")

