def smartlead_get_blacklist(test_id, run_id=None, email_id=None, ip_address=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, client_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "request_id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{os.getpid()}|{time.time()}".encode()).hexdigest()[:24],
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "client_id": client_id,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_accessible_test(test_id_):
        tests = _load("smart_delivery_tests.json")
        if not isinstance(tests, list):
            return None, None
        for t in tests:
            if isinstance(t, dict) and t.get("test_id") == test_id_ and t.get("status") != "deleted":
                cid = t.get("client_id")
                if isinstance(cid, str) and cid:
                    return t, cid
        for t in tests:
            if isinstance(t, dict) and t.get("test_id") == test_id_:
                cid = t.get("client_id")
                if isinstance(cid, str) and cid:
                    return t, cid
        return None, None

    # Validate inputs
    if not isinstance(test_id, str) or not re.match(r"^sl_sdt_[0-9A-Z]{18,}$", test_id):
        _log("smartlead_get_blacklist", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "test_id is invalid.")

    if run_id is not None and not (isinstance(run_id, str) and run_id.strip()):
        _log("smartlead_get_blacklist", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "run_id is malformed.")
    if email_id is not None and not (isinstance(email_id, str) and email_id.strip()):
        _log("smartlead_get_blacklist", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "email_id is malformed.")
    if ip_address is not None and not (isinstance(ip_address, str) and ip_address.strip()):
        _log("smartlead_get_blacklist", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "ip_address is malformed.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("smartlead_get_blacklist", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    if cursor is not None and not isinstance(cursor, str):
        _log("smartlead_get_blacklist", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor is malformed.")

    test, client_id = _pick_accessible_test(test_id)
    if not test:
        _log("smartlead_get_blacklist", "error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Test not found.")

    emails = test.get("emails") or []
    if emails is None:
        emails = []
    if not isinstance(emails, list):
        emails = []

    # Validate run/email existence when specified
    runs = test.get("runs") or []
    if runs is None:
        runs = []
    if not isinstance(runs, list):
        runs = []

    if run_id is not None:
        if not any(isinstance(r, dict) and r.get("run_id") == run_id for r in runs):
            _log("smartlead_get_blacklist", "error", client_id=client_id, extra={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "run_id not found in test.")
    if email_id is not None:
        if not any(isinstance(e, dict) and e.get("email_id") == email_id for e in emails):
            _log("smartlead_get_blacklist", "error", client_id=client_id, extra={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "email_id not found in test.")

    # Extract blacklist hits from email artifacts
    def _as_list(x):
        if isinstance(x, list):
            return x
        if x is None:
            return []
        return [x]

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    hits = []
    for e in emails:
        if not isinstance(e, dict):
            continue
        if email_id is not None and e.get("email_id") != email_id:
            continue
        if run_id is not None and e.get("run_id") != run_id:
            # some stores may not have run_id on email; if absent, allow only when run_id not specified
            continue
        if ip_address is not None and e.get("ip") != ip_address:
            continue

        bh = e.get("blacklist_hits")
        for h in _as_list(bh):
            if isinstance(h, dict):
                provider = h.get("provider") or h.get("blacklist") or h.get("name")
                listed_at = h.get("listed_at") or h.get("observed_at") or e.get("sent_at")
                hits.append({
                    "test_id": test_id,
                    "run_id": e.get("run_id"),
                    "email_id": e.get("email_id"),
                    "sender_account_id": e.get("sender_account_id"),
                    "receiver_mailbox_id": e.get("receiver_mailbox_id"),
                    "ip_address": e.get("ip"),
                    "blacklist": provider,
                    "details": h,
                    "observed_at": listed_at
                })
            elif isinstance(h, str):
                hits.append({
                    "test_id": test_id,
                    "run_id": e.get("run_id"),
                    "email_id": e.get("email_id"),
                    "sender_account_id": e.get("sender_account_id"),
                    "receiver_mailbox_id": e.get("receiver_mailbox_id"),
                    "ip_address": e.get("ip"),
                    "blacklist": h,
                    "details": {"name": h},
                    "observed_at": e.get("sent_at")
                })

    # Sort by observed_at desc then email_id
    hits.sort(key=lambda x: (
        _parse_dt(x.get("observed_at")) or datetime.datetime(1970, 1, 1),
        x.get("email_id") or ""
    ), reverse=True)

    # Cursor handling: opaque base64 JSON {"o": offset}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("o"), int) and obj["o"] >= 0:
                offset = obj["o"]
            else:
                _log("smartlead_get_blacklist", "error", client_id=client_id, extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            _log("smartlead_get_blacklist", "error", client_id=client_id, extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    page = hits[offset:offset + limit]
    next_cursor = None
    if offset + limit < len(hits):
        next_cursor = base64.urlsafe_b64encode(json.dumps({"o": offset + limit}).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("smartlead_get_blacklist", "ok", client_id=client_id, extra={"result_count": len(page)})
    return {
        "data": page,
        "meta": {
            "test_id": test_id,
            "total": len(hits),
            "limit": limit,
            "has_more": bool(next_cursor),
            "next_cursor": next_cursor
        }
    }

def smartlead_get_email_content(test_id, email_id, format=None, **_extra):
