    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_email_content"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, client_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": "sl_req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(test_id, str) or not test_id.strip():
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "test_id"})
            return _err("VALIDATION_ERROR", "test_id is required.", field="test_id")
        test_id = test_id.strip()
        if re.match(r"^sl_sdt_[0-9A-Z]{18,}$", test_id) is None:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "test_id"})
            return _err("VALIDATION_ERROR", "test_id is invalid.", field="test_id")

        if not isinstance(email_id, str) or not email_id.strip():
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "email_id"})
            return _err("VALIDATION_ERROR", "email_id is missing/invalid.", field="email_id")
        email_id = email_id.strip()

        if format is None:
            format = "both"
        if not isinstance(format, str) or format not in ("raw", "html", "both"):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "format"})
            return _err("VALIDATION_ERROR", "format must be one of: raw, html, both.", field="format", allowed=["raw", "html", "both"])

        tests = _load("smart_delivery_tests.json")
        if not isinstance(tests, list): tests = []
        test = next((t for t in tests if isinstance(t, dict) and t.get("test_id") == test_id), None)
        if not test or test.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND", meta={"test_id": test_id})
            return _err("NOT_FOUND", "Smart Delivery test not found.", test_id=test_id)

        client_id = test.get("client_id")
        clients = _load("clients.json")
        if not isinstance(clients, list): clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
        if not client:
            _log("error", client_id=client_id, error_code="UNAUTHORIZED", meta={"client_id": client_id})
            return _err("UNAUTHORIZED", "You do not have access to this client.", client_id=client_id)

        emails = test.get("emails") or []
        if not isinstance(emails, list): emails = []
        email_row = next((e for e in emails if isinstance(e, dict) and e.get("email_id") == email_id), None)
        if not email_row:
            _log("error", client_id=client_id, error_code="NOT_FOUND", meta={"email_id": email_id})
            return _err("NOT_FOUND", "Email not found in test.", test_id=test_id, email_id=email_id)

        # Content may be inline or by reference; return what we have without fabricating.
        raw_ref = email_row.get("raw_content_ref")
        headers_ref = email_row.get("headers_ref")
        html = email_row.get("body_html") or email_row.get("html") or None
        raw = email_row.get("raw") or None

        resp = {
            "test_id": test_id,
            "email_id": email_id,
            "sender_account_id": email_row.get("sender_account_id"),
            "receiver_mailbox_id": email_row.get("receiver_mailbox_id"),
            "sent_at": email_row.get("sent_at"),
            "references": {"raw_content_ref": raw_ref, "headers_ref": headers_ref},
            "content": {}
        }
        if format in ("raw", "both"):
            resp["content"]["raw"] = raw
            resp["content"]["raw_content_ref"] = raw_ref
        if format in ("html", "both"):
            resp["content"]["html"] = html
        _log("success", client_id=client_id)
        return resp
    except Exception:
        _log("error", error_code="VALIDATION_ERROR", meta={"unhandled": True})
        return _err("VALIDATION_ERROR", "Request could not be processed due to an unexpected condition.")

