def smartlead_get_schedule_history(client_id, test_id, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    used_cred = None

    def _log_and_return(payload):
        nonlocal status
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "log_id": "sl_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "smartlead_get_schedule_history",
            "client_id": client_id,
            "credential": used_cred,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z"
        })
        _save("request_logs.json", logs)
        return payload

    # Validation
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-Z]{18}$", client_id):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "client_id is invalid"))
    if not isinstance(test_id, str) or not re.match(r"^sl_sdt_[0-9A-Z]{18}$", test_id):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "test_id is invalid"))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 200"))
    if sort is None:
        sort = "-created_at"
    if sort not in ("created_at", "-created_at"):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "sort must be one of: created_at, -created_at"))
    if cursor is not None and not isinstance(cursor, str):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "cursor must be a string"))

    clients = _load("clients.json")
    if not any(isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted" for c in clients):
        status = "error"
        return _log_and_return(_err("NOT_FOUND", "client not found"))

    tests = _load("smart_delivery_tests.json")
    test = None
    for r in tests:
        if isinstance(r, dict) and r.get("test_id") == test_id and r.get("client_id") == client_id and r.get("status") != "deleted":
            test = r
            break
    if not test:
        status = "error"
        return _log_and_return(_err("NOT_FOUND", "test not found"))

    if test.get("test_type") != "automated":
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "test_id must refer to an automated test"))

    runs = test.get("runs") or []
    if not isinstance(runs, list):
        runs = []

    # Sorting key: run.started_at else run.created_at else run_id as last
    def _dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _run_created_at(run):
        if not isinstance(run, dict):
            return None
        for k in ("created_at", "started_at", "ended_at"):
            d = _dt(run.get(k))
            if d:
                return d
        return None

    rev = sort.startswith("-")
    runs_sorted = []
    for run in runs:
        if isinstance(run, dict):
            runs_sorted.append(run)
    runs_sorted.sort(key=lambda x: (_run_created_at(x) or datetime.datetime(1970, 1, 1), str(x.get("run_id") or "")), reverse=rev)

    # Cursor decode: base64url(json {"offset": int})
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                status = "error"
                return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid"))
            offset = obj["offset"]
        except Exception:
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "cursor is invalid"))

    page = runs_sorted[offset: offset + limit]
    next_cursor = None
    if offset + limit < len(runs_sorted):
        nxt = {"offset": offset + limit}
        enc = base64.urlsafe_b64encode(json.dumps(nxt, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    summary = {
        "test_id": test_id,
        "client_id": client_id,
        "test_type": test.get("test_type"),
        "status": test.get("status"),
        "total_runs": len(runs_sorted)
    }

    return _log_and_return({
        "summary": summary,
        "runs": page,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "total": len(runs_sorted),
        "has_more": bool(next_cursor)
    })

def smartlead_get_ip_details(client_id, email, test_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_ip_details"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": "sl_req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(client_id, str) or re.match(r"^sl_cli_[0-9A-Z]{18}$", (client_id or "")) is None:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "client_id"})
            return _err("VALIDATION_ERROR", "client_id format is invalid.", field="client_id")
        if not isinstance(email, str):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "email"})
            return _err("VALIDATION_ERROR", "email is invalid.", field="email")
        email_norm = email.strip().lower()
        if len(email_norm) > 254 or re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email_norm) is None:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "email"})
            return _err("VALIDATION_ERROR", "email is not a valid email address.", field="email")

        if test_id is not None:
            if not isinstance(test_id, str) or not test_id.strip():
                _log("error", error_code="VALIDATION_ERROR", meta={"field": "test_id"})
                return _err("VALIDATION_ERROR", "test_id must be a string when provided.", field="test_id")
            test_id = test_id.strip()
            # NOTE: schema says {18} but other endpoints accept {18,}; be tolerant.
            if re.match(r"^sl_sdt_[0-9A-Z]{18,}$", test_id) is None:
                _log("error", error_code="VALIDATION_ERROR", meta={"field": "test_id"})
                return _err("VALIDATION_ERROR", "test_id format is invalid.", field="test_id")

        clients = _load("clients.json")
        if not isinstance(clients, list): clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
        if not client:
            _log("error", error_code="NOT_FOUND", meta={"client_id": client_id})
            return _err("NOT_FOUND", "Client not found.", client_id=client_id)

        tests = _load("smart_delivery_tests.json")
        if not isinstance(tests, list): tests = []

        scoped_tests = []
        for t in tests:
            if not isinstance(t, dict):
                continue
            if t.get("client_id") != client_id:
                continue
            if t.get("status") == "deleted":
                continue
            if test_id is not None and t.get("test_id") != test_id:
                continue
            scoped_tests.append(t)

        if test_id is not None and not scoped_tests:
            _log("error", error_code="NOT_FOUND", meta={"test_id": test_id})
            return _err("NOT_FOUND", "Smart Delivery test not found for client.", client_id=client_id, test_id=test_id)

        # Collect IP-related artifacts from emails where sender matches the requested email
        matches = []
        for t in scoped_tests:
            emails = t.get("emails") or []
            if not isinstance(emails, list):
                continue
            for e in emails:
                if not isinstance(e, dict):
                    continue
                # Match either sender mailbox email (when present) or fallback sender_account list
                sender_email = e.get("sender_email") or e.get("from_email") or e.get("email")
                if isinstance(sender_email, str) and sender_email.strip().lower() != email_norm:
                    continue

                ip = e.get("ip") or e.get("sending_ip") or None
                bl = e.get("blacklist_hits")
                if isinstance(bl, list):
                    blacklist_hits = bl
                elif isinstance(bl, dict):
                    blacklist_hits = [bl]
                else:
                    blacklist_hits = []

                matches.append({
                    "test_id": t.get("test_id"),
                    "email_id": e.get("email_id"),
                    "sent_at": e.get("sent_at"),
                    "ip": ip,
                    "blacklist_hits": blacklist_hits,
                })

        # If no sender_email fields exist in dataset, fall back: include any email artifacts that mention the email in content/refs
        if not matches:
            for t in scoped_tests:
                emails = t.get("emails") or []
                if not isinstance(emails, list):
                    continue
                for e in emails:
                    if not isinstance(e, dict):
                        continue
                    hay = " ".join([str(e.get(k) or "") for k in ("raw_content_ref", "headers_ref", "email_id")])
                    if email_norm in hay.lower():
                        ip = e.get("ip") or e.get("sending_ip") or None
                        bl = e.get("blacklist_hits")
                        if isinstance(bl, list):
                            blacklist_hits = bl
                        elif isinstance(bl, dict):
                            blacklist_hits = [bl]
                        else:
                            blacklist_hits = []
                        matches.append({
                            "test_id": t.get("test_id"),
                            "email_id": e.get("email_id"),
                            "sent_at": e.get("sent_at"),
                            "ip": ip,
                            "blacklist_hits": blacklist_hits,
                        })

        if not matches:
            # As per spec this can be NOT_FOUND when email/test scope has no accessible data
            _log("error", error_code="NOT_FOUND", meta={"email": email_norm, "test_id": test_id})
            return _err("NOT_FOUND", "No accessible IP details found for the specified email/scope.", client_id=client_id, email=email_norm, test_id=test_id)

        # Aggregate by IP
        by_ip = {}
        for m in matches:
            ip = m.get("ip") or "unknown"
            entry = by_ip.setdefault(ip, {"ip": ip, "email": email_norm, "tests": set(), "emails": 0, "blacklist_hits": []})
            if m.get("test_id"):
                entry["tests"].add(m["test_id"])
            entry["emails"] += 1
            for hit in m.get("blacklist_hits") or []:
                if isinstance(hit, dict):
                    entry["blacklist_hits"].append(hit)

        rows = []
        for ip, entry in by_ip.items():
            entry["tests"] = sorted(list(entry["tests"]))
            rows.append(entry)

        resp = {
            "client_id": client_id,
            "email": email_norm,
            "test_id": test_id,
            "ips": rows,
            "total_ips": len(rows),
        }
        _log("success")
        return resp
    except Exception:
        _log("error", error_code="VALIDATION_ERROR", meta={"unhandled": True})
        return _err("VALIDATION_ERROR", "Request could not be processed due to an unexpected condition.")

def smartlead_get_mailbox_summary(client_id, folder_id=None, test_type=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_mailbox_summary"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": "sl_req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str):
            return None, _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if cur.strip() == "":
            return 0, None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("ascii") + b"==")
            s = raw.decode("utf-8")
            if s.startswith("offset:"):
                off = int(s.split(":", 1)[1])
            else:
                off = int(s)
            if off < 0:
                raise ValueError()
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    def _encode_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("ascii").rstrip("=")

    try:
        if not isinstance(client_id, str) or re.match(r"^sl_cli_[0-9A-Z]{18}$", (client_id or "")) is None:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "client_id"})
            return _err("VALIDATION_ERROR", "client_id format is invalid.", field="client_id")

        if folder_id is not None:
            if not isinstance(folder_id, str) or re.match(r"^sl_sdf_[0-9A-Z]{18}$", (folder_id or "")) is None:
                _log("error", error_code="VALIDATION_ERROR", meta={"field": "folder_id"})
                return _err("VALIDATION_ERROR", "folder_id format is invalid.", field="folder_id")
            folder_id = folder_id.strip()

        if test_type is not None and test_type not in ("manual", "automated"):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "test_type"})
            return _err("VALIDATION_ERROR", "test_type must be one of: manual, automated.", field="test_type", allowed=["manual", "automated"])

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

        offset, cerr = _decode_cursor(cursor)
        if cerr is not None:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "cursor"})
            return cerr

        if sort is None:
            sort = "email"
        if sort not in ("email", "-email", "created_at", "-created_at"):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "sort"})
            return _err("VALIDATION_ERROR", "sort must be one of: email, -email, created_at, -created_at.", field="sort")

        clients = _load("clients.json")
        if not isinstance(clients, list): clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
        if not client:
            _log("error", error_code="NOT_FOUND", meta={"client_id": client_id})
            return _err("NOT_FOUND", "Client not found.", client_id=client_id)

        if folder_id is not None:
            folders = _load("smart_delivery_folders.json")
            if not isinstance(folders, list): folders = []
            folder = next((f for f in folders if isinstance(f, dict) and f.get("folder_id") == folder_id and f.get("client_id") == client_id), None)
            if not folder or folder.get("status") == "deleted":
                _log("error", error_code="NOT_FOUND", meta={"folder_id": folder_id})
                return _err("NOT_FOUND", "Folder not found for client.", client_id=client_id, folder_id=folder_id)

        tests = _load("smart_delivery_tests.json")
        if not isinstance(tests, list): tests = []

        # Aggregate receiver_mailboxes used in tests (by mailbox_id when available; else by email if present)
        agg = {}
        for t in tests:
            if not isinstance(t, dict):
                continue
            if t.get("client_id") != client_id:
                continue
            if t.get("status") == "deleted":
                continue
            if folder_id is not None and t.get("folder_id") != folder_id:
                continue
            if test_type is not None and t.get("test_type") != test_type:
                continue

            created_at = t.get("created_at")
            rms = t.get("receiver_mailboxes") or []
            if not isinstance(rms, list):
                rms = []
            for m in rms:
                if not isinstance(m, dict):
                    continue
                mid = m.get("mailbox_id") or m.get("receiver_mailbox_id") or m.get("email") or m.get("mailbox")
                if not mid:
                    continue
                row = agg.setdefault(mid, {
                    "mailbox_id": m.get("mailbox_id") or m.get("receiver_mailbox_id") or None,
                    "email": m.get("email") or None,
                    "provider_id": m.get("provider_id") or None,
                    "region": m.get("region") or None,
                    "country": m.get("country") or None,
                    "created_at": created_at,
                    "tests_used_in": set(),
                    "test_count": 0,
                })
                if created_at and (row.get("created_at") is None or str(created_at) < str(row.get("created_at"))):
                    row["created_at"] = created_at
                tid = t.get("test_id")
                if tid and tid not in row["tests_used_in"]:
                    row["tests_used_in"].add(tid)
                    row["test_count"] += 1

        rows = []
        for _, v in agg.items():
            v["tests_used_in"] = sorted(list(v["tests_used_in"]))
            rows.append(v)

        # Sorting
        reverse = sort.startswith("-")
        key = sort[1:] if reverse else sort
        def _k(r):
            val = r.get(key)
            return "" if val is None else str(val).lower()
        rows.sort(key=_k, reverse=reverse)

        total = len(rows)
        page = rows[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = _encode_cursor(next_offset) if has_more else None

        resp = {
            "client_id": client_id,
            "folder_id": folder_id,
            "test_type": test_type,
            "sort": sort,
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "data": page
        }
        _log("success")
