            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate client_id (relax: schema says exact 18 but datastore uses longer sometimes)
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-Z]{18,}$", client_id):
        _log("error", meta={"field": "client_id"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "client_id is malformed.", field="client_id")

    if include_tests is None:
        include_tests = False
    if not isinstance(include_tests, bool):
        _log("error", meta={"field": "include_tests"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_tests must be boolean.", field="include_tests")

    if status is not None and status not in ("active", "deleted"):
        _log("error", meta={"field": "status"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", meta={"field": "limit"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", meta={"field": "cursor"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.", field="cursor")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "name", "-name"):
        _log("error", meta={"field": "sort"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is not supported.", field="sort")

    # Client existence
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    ok_client = False
    for cl in clients:
        if isinstance(cl, dict) and cl.get("client_id") == client_id and cl.get("status") in ("active", "suspended"):
            ok_client = True
            break
    if not ok_client:
        _log("error", meta={"client_id": client_id}, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to this client.", client_id=client_id)

    folders = _load("smart_delivery_folders.json")
    if not isinstance(folders, list):
        folders = []
    tests = _load("smart_delivery_tests.json")
    if not isinstance(tests, list):
        tests = []

    rows = [f for f in folders if isinstance(f, dict) and f.get("client_id") == client_id and (status is None or f.get("status") == status)]
    if status is None:
        # include only active by default
        rows = [f for f in rows if f.get("status") == "active"]

    reverse = sort.startswith("-")
    sort_key = sort[1:] if reverse else sort
    def _k(f):
        v = f.get(sort_key)
        return (v if isinstance(v, str) else "")
    rows.sort(key=_k, reverse=reverse)

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"=" * (-len(cursor) % 4)).decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _log("error", meta={"field": "cursor"}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(rows)
    next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=") if has_more else None

    if include_tests:
        # attach tests (exclude deleted by default unless folder status filter explicitly asks deleted tests? rule: deleted tests excluded from listings by default)
        tests_by_folder = {}
        for t in tests:
            if not isinstance(t, dict):
                continue
            if t.get("client_id") != client_id:
                continue
            if t.get("status") == "deleted":
                continue
            fid = t.get("folder_id")
            tests_by_folder.setdefault(fid, []).append(t)
        for f in page:
            f["tests"] = tests_by_folder.get(f.get("folder_id"), [])

    _log("ok", meta={"returned": len(page), "total": len(rows), "has_more": has_more})
    return {"data": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor, "limit": limit, "cursor": cursor}

