        new_status = _normalize_status(desired_status, payload)
        if new_status is None:
            new_status = existing.get("status")
        if new_status not in ("active", "inactive", "deleted"):
            _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id, record_id=webhook_id)
