        _save("integrations_and_procurement.json", records)
        _log(200, client_id=client_id, campaign_id=campaign_id, record_id=updated.get("record_id"))
        return {"webhook": updated}

    # Create new record
    new_status = _normalize_status(desired_status, payload)
    if new_status is None:
        new_status = "active"  # default to active when creating, unless payload.is_enabled implies otherwise
        if isinstance(payload.get("is_enabled"), bool):
