    if not isinstance(client_id, str) or re.match(r"^sl_cli_[0-9A-Z]{18,}$", client_id) is None:
        _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "client_id is malformed.", field="client_id")

    if campaign_id is not None:
        if not isinstance(campaign_id, str) or re.match(r"^sl_cmp_[0-9A-Z]{18,}$", campaign_id) is None:
            _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
            return _err("VALIDATION_ERROR", "campaign_id is malformed.", field="campaign_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "delivered", "failed", "retrying", "cancelled", "deleted"):
            _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
            return _err("VALIDATION_ERROR", "status is not supported.", field="status")

    dt_from = _parse_dt(created_from)
    dt_to = _parse_dt(created_to)
    if created_from is not None and dt_from is None:
        _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "created_from must be a valid RFC3339 datetime.", field="created_from")
    if created_to is not None and dt_to is None:
        _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "created_to must be a valid RFC3339 datetime.", field="created_to")
    if dt_from is not None and dt_to is not None and dt_from > dt_to:
        _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "created_from must be <= created_to.", field="created_from")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "limit is out of range.", field="limit", min=1, max=200)

    offset = _decode_cursor(cursor)
    if offset is None:
        _log(400, error_code="VALIDATION_ERROR", client_id=client_id, campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    # Authorization: client must exist and not be deleted
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    client_row = None
    for r in clients:
        if isinstance(r, dict) and r.get("client_id") == client_id:
            client_row = r
            break
    if client_row is None or client_row.get("status") == "deleted":
        _log(401, error_code="UNAUTHORIZED", client_id=client_id, campaign_id=campaign_id)
        return _err("UNAUTHORIZED", "You don’t have access to this client.", client_id=client_id)

    # If campaign_id is provided, ensure it exists and belongs to client_id
    if campaign_id is not None:
        campaigns = _load("campaigns.json")
        if not isinstance(campaigns, list):
            campaigns = []
        camp = None
        for c in campaigns:
            if isinstance(c, dict) and c.get("campaign_id") == campaign_id:
                camp = c
                break
        if camp is None:
            _log(404, error_code="NOT_FOUND", client_id=client_id, campaign_id=campaign_id)
            return _err("NOT_FOUND", "Campaign does not exist.", campaign_id=campaign_id)
        if camp.get("client_id") != client_id:
            _log(401, error_code="UNAUTHORIZED", client_id=client_id, campaign_id=campaign_id)
            return _err("UNAUTHORIZED", "Cross-client access is not allowed.", client_id=client_id, campaign_id=campaign_id)

    records = _load("integrations_and_procurement.json")
    if not isinstance(records, list):
        records = []

    events = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "webhook_publish_event":
            continue
        if r.get("client_id") != client_id:
            continue
        if campaign_id is not None and r.get("campaign_id") != campaign_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        created = _parse_dt(r.get("created_at"))
        if dt_from is not None and (created is None or created < dt_from):
            continue
        if dt_to is not None and (created is None or created > dt_to):
            continue
        events.append(r)

    # Sort by created_at desc then record_id asc
    events.sort(key=lambda x: (
        _parse_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1),
        str(x.get("record_id") or "")
    ), reverse=True)

    total = len(events)
    page = events[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    # Aggregated summary across *filtered universe* (not just page)
    summary = {}
    by_campaign = {}
    for e in events:
        st = e.get("status") or "unknown"
        payload = e.get("payload") if isinstance(e.get("payload"), dict) else {}
        ev_name = payload.get("event_name") or "unknown"
        cmp = e.get("campaign_id") or "unknown"

        summary_key = (ev_name, st)
        summary[summary_key] = summary.get(summary_key, 0) + 1

        bc = by_campaign.get(cmp)
        if bc is None:
            bc = {}
            by_campaign[cmp] = bc
        bc_key = (ev_name, st)
        bc[bc_key] = bc.get(bc_key, 0) + 1

    def _pack_counts(d):
        out = []
        for (ev_name, st), cnt in sorted(d.items(), key=lambda k: (k[0][0], k[0][1])):
            out.append({"event_name": ev_name, "status": st, "count": cnt})
        return out

    response = {
        "client_id": client_id,
        "filters": {
            "campaign_id": campaign_id,
            "status": status,
            "created_from": created_from,
            "created_to": created_to
        },
        "events": page,
        "counts": _pack_counts(summary),
        "counts_by_campaign": [
            {"campaign_id": cmp, "counts": _pack_counts(cnts)}
            for cmp, cnts in sorted(by_campaign.items(), key=lambda x: x[0])
        ],
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        }
    }

    _log(200, client_id=client_id, campaign_id=campaign_id)
    return response

def smartlead_retrigger_failed_events(client_id, campaign_id=None, event_ids=None, created_from=None, created_to=None, limit=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept ISO with Z
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _dt_from_row(v):
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    # ---- Validation
    cli_pat = re.compile(r"^sl_cli_[0-9A-Z]{18,}$")
    cmp_pat = re.compile(r"^sl_cmp_[0-9A-Z]{18,}$")
    rec_pat = re.compile(r"^sl_rec_[0-9A-Z]{18,}$")

    if not isinstance(client_id, str) or not cli_pat.match(client_id):
        return _err("VALIDATION_ERROR", "client_id is missing/invalid")

    if campaign_id is not None and (not isinstance(campaign_id, str) or not cmp_pat.match(campaign_id)):
        return _err("VALIDATION_ERROR", "campaign_id is invalid")

    if event_ids is not None:
        if not isinstance(event_ids, list) or len(event_ids) < 1:
            return _err("VALIDATION_ERROR", "event_ids must be a non-empty array when provided")
        for eid in event_ids:
            if not isinstance(eid, str) or not rec_pat.match(eid):
                return _err("VALIDATION_ERROR", "event_ids contains an invalid id", invalid_event_id=eid)

    cf = _parse_dt(created_from)
    if created_from is not None and cf is None:
        return _err("VALIDATION_ERROR", "created_from must be an RFC3339/ISO date-time string")

    ct = _parse_dt(created_to)
    if created_to is not None and ct is None:
        return _err("VALIDATION_ERROR", "created_to must be an RFC3339/ISO date-time string")

    if cf is not None and ct is not None and cf > ct:
        return _err("VALIDATION_ERROR", "created_from must be <= created_to")

    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    # ---- Load store
    clients = _load("clients.json")
    iap = _load("integrations_and_procurement.json")
    request_logs = _load("request_logs.json")

    # ---- Helper: write request log
    def _log(status_code, status_text, credential_used=None, details=None):
        latency_ms = int((time.time() - start) * 1000)
        entry = {
            "request_id": "sl_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "smartlead_retrigger_failed_events",
            "client_id": client_id,
            "credential_used": credential_used,
            "status": status_text,
            "status_code": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
            "details": details or {}
        }
        if isinstance(request_logs, list):
            request_logs.append(entry)
            _save("request_logs.json", request_logs)

    # ---- Quota/rate limit (best-effort if schema not present)
    # If a quotas.json exists, enforce simplistic daily quota and per-minute rate.
    quotas = _load("quotas.json")
    def _enforce_limits():
        if not isinstance(quotas, list):
            return None
        q = None
        for row in quotas:
            if isinstance(row, dict) and row.get("client_id") == client_id and row.get("status", "active") == "active":
                q = row
                break
        if not q:
            return None
        # rate_limit_per_minute, daily_quota
        rate = q.get("rate_limit_per_minute")
        daily = q.get("daily_quota")
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        calls_last_min = 0
        calls_last_day = 0
        for r in request_logs if isinstance(request_logs, list) else []:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                calls_last_min += 1
            if ts >= day_ago:
                calls_last_day += 1
        if isinstance(rate, int) and rate > 0 and calls_last_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(daily, int) and daily > 0 and calls_last_day >= daily:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log(429, "error", details=lim_err["error"])
        return lim_err

    # ---- Auth context (ambient): must find active client
    client_row = None
    for c in clients:
        if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted":
            client_row = c
            break
    if not client_row:
        _log(401, "error", details={"code": "UNAUTHORIZED", "message": "No active client context found"})
        return _err("UNAUTHORIZED", "No active client context found")

    # campaign check if provided
    if campaign_id is not None:
        campaigns = _load("campaigns.json")
        ok_campaign = False
        for cmp in campaigns:
            if isinstance(cmp, dict) and cmp.get("campaign_id") == campaign_id and cmp.get("client_id") == client_id and cmp.get("status") != "deleted":
                ok_campaign = True
                break
        if not ok_campaign:
            _log(404, "error", details={"code": "NOT_FOUND", "message": "campaign_id not found for client"})
            return _err("NOT_FOUND", "campaign_id not found for client")

    MAX_ATTEMPTS = 10
    selected = []
    updated = 0

    # Determine selection mode
    by_ids = event_ids is not None

    # Collect candidates
    candidates = []
    if by_ids:
        idset = set(event_ids)
        for r in iap:
            if not isinstance(r, dict):
                continue
            if r.get("record_id") in idset:
                candidates.append(r)
    else:
        for r in iap:
            if not isinstance(r, dict):
                continue
            candidates.append(r)

    # Filter and apply limit for non-id selection
    filtered = []
    for r in candidates:
        if r.get("client_id") != client_id:
            continue
        if r.get("record_type") != "webhook_publish_event":
            continue
        if r.get("status") != "failed":
            continue
        if campaign_id is not None and r.get("campaign_id") != campaign_id:
            continue
        if cf is not None or ct is not None:
            r_created = _dt_from_row(r.get("created_at"))
            if not r_created:
                # If missing created_at and time filter used, exclude
                continue
            if cf is not None and r_created < cf:
                continue
            if ct is not None and r_created > ct:
                continue
        filtered.append(r)

    if not by_ids:
        lim = limit if isinstance(limit, int) else 200
        filtered = filtered[:lim]

    # For by_ids, if none matched ids at all: NOT_FOUND (mutation must have effect)
    if by_ids and len(filtered) == 0:
        _log(404, "error", details={"code": "NOT_FOUND", "message": "No failed webhook publish events found for given event_ids"})
        return _err("NOT_FOUND", "No failed webhook publish events found for given event_ids")

    # Apply transition failed -> retrying and bump attempt/next_retry_at
    for r in filtered:
        payload = r.get("payload")
        if not isinstance(payload, dict):
            payload = {}
            r["payload"] = payload

        attempt = payload.get("attempt", 1)
        if not isinstance(attempt, int):
            attempt = 1

        if attempt >= MAX_ATTEMPTS:
            selected.append({
                "record_id": r.get("record_id"),
                "campaign_id": r.get("campaign_id"),
                "event_name": payload.get("event_name"),
                "status": r.get("status"),
                "attempt": attempt,
                "action": "skipped_max_attempts"
            })
            continue

        # Transition validation per schema: failed -> retrying allowed
        r["status"] = "retrying"
        payload["attempt"] = attempt + 1
        payload["next_retry_at"] = (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) + datetime.timedelta(minutes=5)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        r["updated_at"] = now
        updated += 1

        selected.append({
            "record_id": r.get("record_id"),
            "campaign_id": r.get("campaign_id"),
            "event_name": payload.get("event_name"),
            "status": r.get("status"),
            "attempt": payload["attempt"],
            "action": "requeued"
        })

    if updated == 0:
        # No success without effect: if selection existed but all skipped due to max attempts, treat as conflict
        _log(409, "error", details={"code": "CONFLICT", "message": "No events were re-queued (max attempts reached or not eligible)"})
        return _err("CONFLICT", "No events were re-queued (max attempts reached or not eligible)", selected=len(filtered), requeued=0)

    _save("integrations_and_procurement.json", iap)

    resp = {
        "client_id": client_id,
        "campaign_id": campaign_id,
        "selection_mode": "event_ids" if by_ids else "filters",
        "selected_count": len(filtered),
        "requeued_count": updated,
        "max_attempts": MAX_ATTEMPTS,
        "results": selected
    }
    _log(200, "ok", details={"selected": len(filtered), "requeued": updated})
    return resp

def smartlead_add_client(name, status=None, whitelabel_enabled=None, whitelabel_config=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_add_client"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, client_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": "sl_req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _gen_client_id(existing_ids):
        # 18-char base32-ish uppercase token
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(20):
            token = "".join(alphabet[b % len(alphabet)] for b in os.urandom(18))
            cid = "sl_cli_" + token[:18]
            if cid not in existing_ids:
                return cid
        return "sl_cli_" + os.urandom(12).hex().upper()[:18]

    try:
        if not isinstance(name, str) or not name.strip():
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "name"})
            return _err("VALIDATION_ERROR", "name is missing/blank.", field="name")
        name_clean = name.strip()

        if status is None:
            status = "active"
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted.", field="status", allowed=["active", "suspended", "deleted"])

        if whitelabel_enabled is None:
            whitelabel_enabled = False
        if not isinstance(whitelabel_enabled, bool):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "whitelabel_enabled"})
            return _err("VALIDATION_ERROR", "whitelabel_enabled must be boolean.", field="whitelabel_enabled")

        if whitelabel_config is not None and not isinstance(whitelabel_config, dict):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "whitelabel_config"})
            return _err("VALIDATION_ERROR", "whitelabel_config must be an object when provided.", field="whitelabel_config")

        if not whitelabel_enabled and whitelabel_config is not None and len(whitelabel_config) > 0:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "whitelabel_config"})
            return _err("VALIDATION_ERROR", "whitelabel_config cannot be provided when whitelabel_enabled is false.", field="whitelabel_config")

        clients = _load("clients.json")
        if not isinstance(clients, list): clients = []

        # Unique(lower(name)) where status != 'deleted'
        nm = name_clean.lower()
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") == "deleted":
                continue
            if isinstance(c.get("name"), str) and c.get("name").strip().lower() == nm:
                _log("error", error_code="CONFLICT", meta={"name": name_clean})
                return _err("CONFLICT", "A client with the same name already exists.", name=name_clean)

        existing_ids = {c.get("client_id") for c in clients if isinstance(c, dict) and isinstance(c.get("client_id"), str)}
        client_id = _gen_client_id(existing_ids)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "client_id": client_id,
            "name": name_clean,
            "status": status,
            "whitelabel_enabled": bool(whitelabel_enabled),
            "whitelabel_config": (whitelabel_config if whitelabel_enabled else None),
            "created_at": now,
            "updated_at": now
        }
        clients.append(row)
        _save("clients.json", clients)

        _log("success", client_id=client_id)
        return {"client": row}
    except Exception:
        _log("error", error_code="VALIDATION_ERROR", meta={"unhandled": True})
        return _err("VALIDATION_ERROR", "Request could not be processed due to an unexpected condition.")

def smartlead_fetch_all_clients(status=None, whitelabel_enabled=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
