    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, "error", details={"code": "VALIDATION_ERROR", "message": "limit must be between 1 and 200"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    # Cursor decode: base64 of json {"offset": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log(400, "error", details={"code": "VALIDATION_ERROR", "message": "cursor is invalid"})
            return _err("VALIDATION_ERROR", "cursor is invalid")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                raise ValueError("bad offset")
            offset = off
        except Exception:
            _log(400, "error", details={"code": "VALIDATION_ERROR", "message": "cursor is invalid"})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Filter
    rows = []
    for c in clients if isinstance(clients, list) else []:
        if not isinstance(c, dict):
