        if whitelabel_enabled is not None and c.get("whitelabel_enabled") != whitelabel_enabled:
            continue
        rows.append(c)

    # Sort
    def _key(r):
        v = r.get(sort_by)
        if sort_by == "name":
            return (v or "").lower()
        return v or ""
    reverse = (sort_order == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        nxt = {"offset": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(nxt).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        },
        "sort": {"sort_by": sort_by, "sort_order": sort_order},
        "filters": {"status": status, "whitelabel_enabled": whitelabel_enabled}
    }
    _log(200, "ok", details={"returned": len(page), "total": total})
