def smartlead_search_domain(client_id, query, max_price_usd=None, tld_allowlist=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, random, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- usage log helpers (best-effort; schema not provided) ---
    def _log(status, used_client_id=None, meta=None):
        usage_files = ["request_logs.json", "usage.json", "audit_logs.json", "requests.json"]
        row = {
            "request_id": "sl_req_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").lower(),
            "endpoint": "smartlead_search_domain",
            "client_id": used_client_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta:
            row["meta"] = meta
        for fn in usage_files:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                break

    # --- validation ---
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-HJKMNP-TV-Z]{18,}$", client_id):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "client_id is missing or invalid")
    if not isinstance(query, str) or not query.strip():
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "query is missing or invalid")

    if max_price_usd is None:
        max_price = 15.0
    else:
        if not isinstance(max_price_usd, (int, float)) or isinstance(max_price_usd, bool):
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "max_price_usd must be a number")
        if max_price_usd <= 0:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "max_price_usd must be positive")
        max_price = float(max_price_usd)

    if limit is None:
        limit_i = 25
    else:
        if not isinstance(limit, int) or isinstance(limit, bool):
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_i = limit

    allow_tlds = None
    if tld_allowlist is not None:
        if not isinstance(tld_allowlist, list):
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tld_allowlist must be an array of strings")
        allow_tlds = []
        for t in tld_allowlist:
            if not isinstance(t, str) or not re.match(r"^\.[a-z0-9-]{2,}$", t):
                _log("error", client_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid TLD in tld_allowlist", tld=t)
            allow_tlds.append(t.lower())
        # dedupe preserve order
        seen = set()
        allow_tlds = [x for x in allow_tlds if not (x in seen or seen.add(x))]

    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")

    clients = _load("clients.json")
    client_row = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
    if not client_row:
        _log("error", client_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Client not found")

    # --- fetch vendor catalog (domain_vendor records) ---
    iap = _load("integrations_and_procurement.json")
    vendors = [
        r for r in iap
        if isinstance(r, dict)
        and r.get("record_type") == "domain_vendor"
        and r.get("status") == "active"
        and isinstance(r.get("payload"), dict)
    ]

    # Build deterministic-but-varied suggestions list seeded by query+client_id
    q = query.strip().lower()
    q_clean = re.sub(r"[^a-z0-9-]+", "-", q).strip("-")
    if not q_clean:
        q_clean = "domain"
    q_clean = q_clean[:40]

    default_tlds = [".com", ".io", ".co", ".net", ".ai", ".app", ".dev", ".xyz", ".me", ".us"]
    tlds = allow_tlds if allow_tlds is not None else default_tlds

    # prices: under 15 only (per business rule), also allow caller lower max
    cap = min(max_price, 15.0)

    # pagination: cursor is base64url of integer offset
    def _decode_cursor(cur):
        try:
            raw = cur.encode("utf-8")
            pad = b"=" * ((4 - (len(raw) % 4)) % 4)
            off = int(base64.urlsafe_b64decode(raw + pad).decode("utf-8"))
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        return base64.urlsafe_b64encode(str(off).encode("utf-8")).decode("utf-8").rstrip("=")

    offset = 0
    if cursor:
        offset = _decode_cursor(cursor)
        if offset is None:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # generate a pool (fixed size) then paginate over it
    seed_bytes = hashlib.sha256((client_id + "|" + q).encode("utf-8")).digest()
    seed_int = int.from_bytes(seed_bytes[:8], "big")
    rnd = random.Random(seed_int)

    # base patterns
    suffixes = ["", "hq", "team", "mail", "get", "try", "app", "ai", "labs", "crm", "sales", "send", "inbox", "hub", "pro"]
    prefixes = ["", "go", "use", "get", "try", "join", "my", "the"]
    # ensure query itself appears
    candidates = []

    def _mk_domain(label, tld):
        label = re.sub(r"-{2,}", "-", label).strip("-")
        if not label:
            label = "domain"
        return f"{label}{tld}"

    # Expand candidates
    for tld in tlds:
        candidates.append(_mk_domain(q_clean, tld))
    for _ in range(200):
        tld = rnd.choice(tlds) if tlds else ".com"
        p = rnd.choice(prefixes)
        s = rnd.choice(suffixes)
        parts = []
        if p:
            parts.append(p)
        parts.append(q_clean)
        if s:
            parts.append(s)
        label = "-".join([x for x in parts if x])
        candidates.append(_mk_domain(label, tld))

    # dedupe preserve
    seen = set()
    pool = []
    for d in candidates:
        if d not in seen:
            seen.add(d)
            pool.append(d)

    # pricing + vendor assignment
    vendor_ids = [v.get("record_id") for v in vendors if isinstance(v.get("record_id"), str)]
    if not vendor_ids:
        # no active vendors: still create a cache record with empty results (realistic)
        vendor_ids = []

    results = []
    for dom in pool:
        # deterministic price 8-14.99
        h = hashlib.md5((dom + "|" + q).encode("utf-8")).digest()
        price = 8.0 + (int.from_bytes(h[:2], "big") % 700) / 100.0  # 8.00 - 14.99
        if price >= cap:
            continue
        vendor_record_id = vendor_ids[int.from_bytes(h[2:4], "big") % len(vendor_ids)] if vendor_ids else None
        results.append({
            "domain": dom,
            "tld": "." + dom.split(".")[-1] if "." in dom else None,
            "price_usd": round(price, 2),
            "currency": "USD",
            "availability": "available",
            "vendor_record_id": vendor_record_id,
        })

    # stable sort: lowest price, then domain
    results.sort(key=lambda r: (r.get("price_usd", 9999), r.get("domain", "")))

    total = len(results)
    page = results[offset: offset + limit_i]
    next_off = offset + len(page)
    next_cursor = _encode_cursor(next_off) if next_off < total else None

    # --- write/update cache record (record_type='domain_search_cache') ---
    # enforce "creates/updates a ... cache entry" with expiry; payload: {query, results[], expires_at}
    expires_at = (datetime.datetime.utcnow() + datetime.timedelta(hours=6)).replace(microsecond=0).isoformat() + "Z"

    # purge expired cache entries opportunistically
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    iap2 = []
    now_dt = _parse_dt(now)
    for r in iap:
        if isinstance(r, dict) and r.get("record_type") == "domain_search_cache" and r.get("client_id") == client_id:
            payload = r.get("payload") if isinstance(r.get("payload"), dict) else {}
            exp = _parse_dt(payload.get("expires_at"))
            if exp is not None and now_dt is not None and exp <= now_dt:
                continue
        iap2.append(r)
    iap = iap2

    # find existing by query (best-effort key)
    existing = None
    for r in iap:
        if isinstance(r, dict) and r.get("record_type") == "domain_search_cache" and r.get("client_id") == client_id:
            payload = r.get("payload") if isinstance(r.get("payload"), dict) else {}
            if payload.get("query") == q:
                existing = r
                break

    # only store under-$15 results in cache (already enforced), store full (unpaginated) list for repeat pages
    cache_payload = {"query": q, "results": results, "expires_at": expires_at}
    if existing:
        existing["payload"] = cache_payload
        existing["status"] = existing.get("status") or "active"
        existing["updated_at"] = now
    else:
        rec_id = "sl_rec_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").upper()
        iap.append({
            "record_id": rec_id,
            "client_id": client_id,
            "record_type": "domain_search_cache",
            "campaign_id": None,
            "status": "active",
            "payload": cache_payload,
            "created_at": now,
            "updated_at": now,
        })
    _save("integrations_and_procurement.json", iap)

    resp = {
        "client_id": client_id,
        "query": query,
        "max_price_usd": cap,
        "tld_allowlist": allow_tlds,
        "limit": limit_i,
        "cursor": cursor,
        "total": total,
        "domains": page,
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
    }
    _log("ok", client_id, {"returned": len(page), "total": total})
    return resp

def smartlead_auto_generate_mailboxes(client_id, domain, first_name, last_name, mailbox_count, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_client_id=None, meta=None):
        usage_files = ["request_logs.json", "usage.json", "audit_logs.json", "requests.json"]
        row = {
            "request_id": "sl_req_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").lower(),
            "endpoint": "smartlead_auto_generate_mailboxes",
            "client_id": used_client_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta:
            row["meta"] = meta
        for fn in usage_files:
            if os.path.exists(os.path.join(_DB, fn)):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                break

    # validation
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-HJKMNP-TV-Z]{18,}$", client_id):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "client_id is missing or invalid")
    for k, v in [("domain", domain), ("first_name", first_name), ("last_name", last_name)]:
        if not isinstance(v, str) or not v.strip():
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{k} is missing or invalid")
    if not isinstance(mailbox_count, int) or isinstance(mailbox_count, bool):
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "mailbox_count must be an integer")
    if mailbox_count < 1 or mailbox_count > 200:
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "mailbox_count must be between 1 and 200")

    clients = _load("clients.json")
    client_row = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
    if not client_row:
        _log("error", client_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Client not found")

    dom = domain.strip().lower()
    # very light domain validation
    if "@" in dom or dom.startswith(".") or dom.endswith(".") or len(dom) > 253:
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "domain is invalid")

    def _slug(s):
        s = s.strip().lower()
        s = re.sub(r"[^a-z0-9]+", "", s)
        return s

    fn = _slug(first_name)
    ln = _slug(last_name)
    if not fn or not ln:
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "first_name/last_name must contain alphanumeric characters")

    base_patterns = [
        "{first}.{last}",
        "{first}{last}",
        "{f}{last}",
        "{first}{l}",
        "{last}.{first}",
        "{last}{first}",
        "{first}",
        "{last}",
        "{first}-{last}",
        "{f}.{last}",
        "{first}.{l}",
    ]

    # generate unique local parts
    out = []
    used = set()

    def _add(local_part, display_name=None):
        lp = local_part.lower()
        if not lp or lp in used:
            return
        used.add(lp)
        item = {"local_part": lp, "email": f"{lp}@{dom}"}
        if display_name:
            item["display_name"] = display_name
        out.append(item)

    display_name = f"{first_name.strip()} {last_name.strip()}"

    for pat in base_patterns:
        if len(out) >= mailbox_count:
            break
        lp = pat.format(first=fn, last=ln, f=fn[0], l=ln[0])
        _add(lp, display_name)

    # add numbered variants if still short
    n = 1
    while len(out) < mailbox_count and n <= 999:
        for pat in ["{first}.{last}{n}", "{f}{last}{n}", "{first}{l}{n}", "{first}{n}"]:
            if len(out) >= mailbox_count:
                break
            lp = pat.format(first=fn, last=ln, f=fn[0], l=ln[0], n=n)
            _add(lp, display_name)
        n += 1

    # create mailbox_generation_plan record
    iap = _load("integrations_and_procurement.json")
    rec_id = "sl_rec_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").upper()
    payload = {
        "base_domain": dom,
        "people": [{"first_name": first_name.strip(), "last_name": last_name.strip()}],
        "pattern": "auto",
