        "total_generated": len(out),
    }
    _log("ok", client_id, {"generated": len(out), "plan_record_id": rec_id})
    return resp

def smartlead_place_order_mailboxes(client_id, domain, vendor_record_id, mailboxes, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_client_id=None, meta=None):
        usage_files = ["request_logs.json", "usage.json", "audit_logs.json", "requests.json"]
        row = {
            "request_id": "sl_req_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").lower(),
            "endpoint": "smartlead_place_order_mailboxes",
            "client_id": used_client_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta:
            row["meta"] = meta
        for fn in usage_files:
            if os.path.exists(os.path.join(_DB, fn)):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                break

    # validation
    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-HJKMNP-TV-Z]{18,}$", client_id):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "client_id is missing or invalid")
    if not isinstance(domain, str) or not domain.strip():
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "domain is missing or invalid")
    if not isinstance(vendor_record_id, str) or not re.match(r"^sl_rec_[0-9A-HJKMNP-TV-Z]{18,}$", vendor_record_id):
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vendor_record_id is missing or invalid")
    if not isinstance(mailboxes, list) or len(mailboxes) < 1:
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "mailboxes must be a non-empty array")

    dom = domain.strip().lower()
    if "@" in dom or dom.startswith(".") or dom.endswith(".") or len(dom) > 253:
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "domain is invalid")

    parsed_mailboxes = []
    seen_lp = set()
    for i, mb in enumerate(mailboxes):
        if not isinstance(mb, dict):
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Each mailbox must be an object", index=i)
        if "local_part" not in mb:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Mailbox local_part is required", index=i)
        lp = mb.get("local_part")
        if not isinstance(lp, str) or not lp.strip():
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Mailbox local_part must be a non-empty string", index=i)
        lp2 = lp.strip().lower()
        if lp2 in seen_lp:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Duplicate mailbox local_part in request", local_part=lp2)
        seen_lp.add(lp2)
        disp = mb.get("display_name")
        if disp is not None and not isinstance(disp, str):
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "display_name must be a string when provided", index=i)
        parsed_mailboxes.append({"local_part": lp2, "display_name": disp})

    clients = _load("clients.json")
    client_row = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
    if not client_row:
        _log("error", client_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Client not found")

    iap = _load("integrations_and_procurement.json")

    vendor_row = next(
        (r for r in iap
         if isinstance(r, dict)
         and r.get("record_id") == vendor_record_id
         and r.get("record_type") == "domain_vendor"
         and r.get("status") == "active"
         and isinstance(r.get("payload"), dict)
         and r.get("payload", {}).get("vendor_id")),
        None
    )
    if not vendor_row:
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vendor_record_id does not refer to an active domain vendor")

    vendor_id = vendor_row["payload"]["vendor_id"]

    # enforce purchased_domain uniqueness per client among non-deleted purchased_domain
    for r in iap:
        if isinstance(r, dict) and r.get("record_type") == "purchased_domain" and r.get("client_id") == client_id and r.get("status") != "deleted":
            payload = r.get("payload") if isinstance(r.get("payload"), dict) else {}
            if payload.get("domain", "").lower() == dom:
                _log("error", client_id, {"code": "CONFLICT"})
                return _err("CONFLICT", "Domain already purchased for this client", domain=dom)

    # idempotency: if an existing mailbox_order for same client+domain+vendor with same mailboxes exists and is not cancelled/deleted, return it
    def _norm_mbs(mbs):
        return sorted(
            [{"local_part": m.get("local_part"), "display_name": m.get("display_name")} for m in mbs],
            key=lambda x: x["local_part"]
        )

    desired_norm = _norm_mbs(parsed_mailboxes)
    for r in iap:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "mailbox_order" or r.get("client_id") != client_id:
            continue
        if r.get("status") not in ("placed", "fulfilled"):
            continue
        payload = r.get("payload") if isinstance(r.get("payload"), dict) else {}
        if payload.get("vendor_id") != vendor_id:
            continue
        domains = payload.get("domains") if isinstance(payload.get("domains"), list) else []
        if not any(isinstance(d, str) and d.lower() == dom for d in domains):
            continue
        existing_mbs = payload.get("mailboxes") if isinstance(payload.get("mailboxes"), list) else []
        if _norm_mbs(existing_mbs) == desired_norm:
            # also return associated purchased_domain if fulfilled
            purchased = [
                x for x in iap
                if isinstance(x, dict)
                and x.get("record_type") == "purchased_domain"
                and x.get("client_id") == client_id
                and x.get("status") != "deleted"
                and isinstance(x.get("payload"), dict)
                and x["payload"].get("order_record_id") == r.get("record_id")
            ]
            _log("ok", client_id, {"idempotent": True, "order_record_id": r.get("record_id")})
            return {"client_id": client_id, "order": r, "purchased_domains": purchased, "idempotent": True}

    # create mailbox_order placed
    order_id = "sl_rec_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").upper()
    # simple pricing model: $10 domain + $1 per mailbox
    total_usd = round(10.0 + 1.0 * len(parsed_mailboxes), 2)
    external_order_id = "ext_" + base64.b32encode(os.urandom(8)).decode("utf-8").rstrip("=").lower()

    order_payload = {
        "vendor_id": vendor_id,
        "domains": [dom],
        "mailboxes": parsed_mailboxes,
        "total_usd": total_usd,
        "external_order_id": external_order_id,
    }
    order_row = {
        "record_id": order_id,
        "client_id": client_id,
        "record_type": "mailbox_order",
        "campaign_id": None,
        "status": "placed",
        "payload": order_payload,
        "created_at": now,
        "updated_at": now,
    }
    iap.append(order_row)

    # fulfill immediately by creating purchased_domain (status='fulfilled') per domain
    purchased_id = "sl_rec_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").upper()
    purchased_payload = {
        "domain": dom,
        "vendor_id": vendor_id,
        "order_record_id": order_id,
        "mailboxes": [{"local_part": m["local_part"], "display_name": m.get("display_name"), "email": f"{m['local_part']}@{dom}"} for m in parsed_mailboxes],
        "dns_status": "pending",
    }
    purchased_row = {
        "record_id": purchased_id,
        "client_id": client_id,
        "record_type": "purchased_domain",
        "campaign_id": None,
        "status": "fulfilled",
        "payload": purchased_payload,
        "created_at": now,
        "updated_at": now,
    }
    iap.append(purchased_row)

    # update order to fulfilled (legal transition placed->fulfilled per lifecycle)
    order_row["status"] = "fulfilled"
    order_row["updated_at"] = now

    _save("integrations_and_procurement.json", iap)
    _log("ok", client_id, {"order_record_id": order_id, "purchased_record_id": purchased_id, "fulfilled": True})

    return {
        "client_id": client_id,
        "order": order_row,
        "purchased_domains": [purchased_row],
        "idempotent": False,
    }

def smartlead_get_domain_list(client_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, used_client_id=None, meta=None):
        usage_files = ["request_logs.json", "usage.json", "audit_logs.json", "requests.json"]
        row = {
            "request_id": "sl_req_" + base64.b32encode(os.urandom(12)).decode("utf-8").rstrip("=").lower(),
            "endpoint": "smartlead_get_domain_list",
            "client_id": used_client_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta:
            row["meta"] = meta
        for fn in usage_files:
            if os.path.exists(os.path.join(_DB, fn)):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                break

    if not isinstance(client_id, str) or not re.match(r"^sl_cli_[0-9A-HJKMNP-TV-Z]{18,}$", client_id):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "client_id is missing or invalid")

    allowed_status = {"active","inactive","queued","delivered","failed","retrying","cancelled","draft","placed","fulfilled","deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status is invalid")

    if limit is None:
        limit_i = 25
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 100:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_i = limit

    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        _log("error", client_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")

    clients = _load("clients.json")
    client_row = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
    if not client_row:
        _log("error", client_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Client not found")

    def _decode_cursor(cur):
        try:
            raw = cur.encode("utf-8")
            pad = b"=" * ((4 - (len(raw) % 4)) % 4)
            off = int(base64.urlsafe_b64decode(raw + pad).decode("utf-8"))
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        return base64.urlsafe_b64encode(str(off).encode("utf-8")).decode("utf-8").rstrip("=")

    offset = 0
    if cursor:
        offset = _decode_cursor(cursor)
        if offset is None:
            _log("error", client_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    iap = _load("integrations_and_procurement.json")
    rows = [
        r for r in iap
        if isinstance(r, dict)
        and r.get("record_type") == "purchased_domain"
        and r.get("client_id") == client_id
        and r.get("status") != "deleted"
    ]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # sort newest first
    def _k(r):
        return (r.get("created_at") or "", r.get("record_id") or "")
    rows.sort(key=_k, reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit_i]
    next_off = offset + len(page)
    next_cursor = _encode_cursor(next_off) if next_off < total else None

    _log("ok", client_id, {"returned": len(page), "total": total})
    return {
        "client_id": client_id,
        "status": status,
        "limit": limit_i,
        "cursor": cursor,
        "total": total,
        "domains": page,
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
    }

def smartlead_list_clients(status=None, search=None, limit=None, cursor=None, sort_by=None, sort_order=None, include_deleted=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_out = "success"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_value, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_value,
            "error_code": error_code,
            "credential_id": None,
            "client_id": None,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if status is not None and status not in ("active", "suspended", "deleted"):
        status_out = "error"
        _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if search is not None and not isinstance(search, str):
        status_out = "error"
        _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid search.", field="search")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        status_out = "error"
        _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        status_out = "error"
        _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "name"):
        status_out = "error"
        _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        status_out = "error"
        _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        status_out = "error"
        _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid include_deleted.", field="include_deleted")

    # Ambient auth: no explicit credential; list all clients in store
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []

    # Filters
    rows = clients[:]
    if not include_deleted:
        rows = [c for c in rows if isinstance(c, dict) and c.get("status") != "deleted"]
    else:
        rows = [c for c in rows if isinstance(c, dict)]

    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    if search:
        s = search.strip().lower()
        if s:
            rows = [c for c in rows if isinstance(c.get("name"), str) and s in c["name"].lower()]

    # Sorting
    def _sort_key(c):
        v = c.get(sort_by)
        if sort_by == "name":
            return ("" if v is None else str(v).lower())
        return "" if v is None else str(v)
    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Pagination via cursor (base64 index)
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor + "===").decode("utf-8")
            if not raw.startswith("idx:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                start = 0
        except Exception:
            status_out = "error"
            _log("smartlead_list_clients", status_out, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(("idx:%d" % (start + limit)).encode("utf-8")).decode("ascii").rstrip("=")

    _log("smartlead_list_clients", status_out)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

