    t0 = time.time()
    status_out = "success"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_value, error_code=None, cli=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_value,
            "error_code": error_code,
            "credential_id": None,
            "client_id": cli,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(client_id, str):
        status_out = "error"
        _log("smartlead_update_client_status", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "client_id must be a string.", field="client_id")
    if not re.match(r"^sl_cli_[0-9A-HJKMNP-TV-Z]{18,}$", client_id):
        status_out = "error"
        _log("smartlead_update_client_status", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "client_id is malformed.", field="client_id")

    if status not in ("active", "suspended", "deleted"):
        status_out = "error"
        _log("smartlead_update_client_status", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []

    idx = None
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("client_id") == client_id:
            idx = i
            break

    if idx is None:
        status_out = "error"
        _log("smartlead_update_client_status", status_out, "NOT_FOUND", cli=client_id)
        return _err("NOT_FOUND", "Client not found.", client_id=client_id)

    rec = clients[idx]
    cur = rec.get("status")
    transitions = {
        "active": ["suspended", "deleted"],
        "suspended": ["active", "deleted"],
        "deleted": []
    }
    if cur not in transitions:
        status_out = "error"
        _log("smartlead_update_client_status", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Client has invalid current status in datastore.", field="status", current_status=cur)

    if status == cur:
        # Idempotent: return current record unchanged
        _log("smartlead_update_client_status", status_out, cli=client_id)
        return {"data": rec}

    if status not in transitions[cur]:
        status_out = "error"
        _log("smartlead_update_client_status", status_out, "INVALID_TRANSITION", cli=client_id)
        return _err("INVALID_TRANSITION", "Requested status transition is not allowed.", from_status=cur, to_status=status)

    # Apply change
    now = _now_iso()
    rec["status"] = status
    rec["updated_at"] = now

    # Enforce constraint: whitelabel_enabled=false implies whitelabel_config null OR defaults.
    # We can't validate "defaults" without schema; enforce minimally: if disabled and config is a non-empty dict -> conflict.
    if rec.get("whitelabel_enabled") is False:
        cfg = rec.get("whitelabel_config")
        if isinstance(cfg, dict) and len(cfg.keys()) > 0:
            status_out = "error"
            _log("smartlead_update_client_status", status_out, "CONFLICT", cli=client_id)
            return _err("CONFLICT", "whitelabel_config must be null/empty when whitelabel_enabled is false.", field="whitelabel_config")

    clients[idx] = rec
    _save("clients.json", clients)

    _log("smartlead_update_client_status", status_out, cli=client_id)
    return {"data": rec}

def smartlead_list_folders(client_id, status=None, search=None, limit=None, cursor=None, sort_by=None, sort_order=None, include_deleted=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_out = "success"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_value, error_code=None, cli=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": "sl_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_value,
            "error_code": error_code,
            "credential_id": None,
            "client_id": cli,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(client_id, str):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "client_id must be a string.", field="client_id")
    if not re.match(r"^sl_cli_[0-9A-HJKMNP-TV-Z]{18,}$", client_id):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "client_id is malformed.", field="client_id")

    if status is not None and status not in ("active", "deleted"):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if search is not None and not isinstance(search, str):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid search.", field="search")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "name"):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        status_out = "error"
        _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
        return _err("VALIDATION_ERROR", "Invalid include_deleted.", field="include_deleted")

    # Authorization (ambient): must at least have access to the client; in this store, existence implies access.
    clients = _load("clients.json")
    if not isinstance(clients, list):
        clients = []
    if not any(isinstance(c, dict) and c.get("client_id") == client_id for c in clients):
        # prefer UNAUTHORIZED per contract set (tool text says FORBIDDEN, but allowed codes list doesn't include it)
        status_out = "error"
        _log("smartlead_list_folders", status_out, "UNAUTHORIZED", cli=client_id)
        return _err("UNAUTHORIZED", "Not authorized for this client.", client_id=client_id)

    folders = _load("smart_delivery_folders.json")
    if not isinstance(folders, list):
        folders = []

    rows = [f for f in folders if isinstance(f, dict) and f.get("client_id") == client_id]

    if not include_deleted:
        rows = [f for f in rows if f.get("status") != "deleted"]

    if status is not None:
        rows = [f for f in rows if f.get("status") == status]

    if search:
        s = search.strip().lower()
        if s:
            rows = [f for f in rows if isinstance(f.get("name"), str) and s in f["name"].lower()]

    def _sort_key(f):
        v = f.get(sort_by)
        if sort_by == "name":
            return ("" if v is None else str(v).lower())
        return "" if v is None else str(v)
    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor + "===").decode("utf-8")
            if not raw.startswith("idx:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                start = 0
        except Exception:
            status_out = "error"
            _log("smartlead_list_folders", status_out, "VALIDATION_ERROR", cli=client_id)
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    total = len(rows)
    page = rows[start:start + limit]
    has_more = (start + limit) < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(("idx:%d" % (start + limit)).encode("utf-8")).decode("ascii").rstrip("=")

    _log("smartlead_list_folders", status_out, cli=client_id)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

def smartlead_get_folder(folder_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0251000" if __import__("os").path.isdir("./environment_mix/0251000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smartlead_get_folder"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, client_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": "sl_req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "client_id": client_id,
            "credential_used": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    try:
        if folder_id is None or not isinstance(folder_id, str):
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "folder_id"})
            return _err("VALIDATION_ERROR", "folder_id must be a string.", field="folder_id")
        folder_id = folder_id.strip()
        if re.match(r"^sl_fld_[0-9A-HJKMNP-TV-Z]{18,}$", folder_id) is None:
            _log("error", error_code="VALIDATION_ERROR", meta={"field": "folder_id"})
            return _err("VALIDATION_ERROR", "folder_id is malformed.", field="folder_id")

        # This endpoint uses a different id prefix than the stored folders; support both by looking up as-is
        folders = _load("smart_delivery_folders.json")
        if not isinstance(folders, list): folders = []
        folder = next((f for f in folders if isinstance(f, dict) and f.get("folder_id") == folder_id), None)

        # If nothing found, also try mapping sl_fld_ -> sl_sdf_ (common mismatch between public/private ids)
        if folder is None and folder_id.startswith("sl_fld_"):
            alt = "sl_sdf_" + folder_id[len("sl_fld_"):]
            folder = next((f for f in folders if isinstance(f, dict) and f.get("folder_id") == alt), None)
            folder_id = alt if folder else folder_id

        if not folder or folder.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND", meta={"folder_id": folder_id})
            return _err("NOT_FOUND", "Folder not found.", folder_id=folder_id)

        client_id = folder.get("client_id")
        clients = _load("clients.json")
        if not isinstance(clients, list): clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("client_id") == client_id and c.get("status") != "deleted"), None)
        if not client:
            _log("error", client_id=client_id, error_code="UNAUTHORIZED", meta={"client_id": client_id})
            return _err("UNAUTHORIZED", "You do not have access to this folder.", folder_id=folder_id)

        _log("success", client_id=client_id)
        return {"folder": folder}
    except Exception:
        _log("error", error_code="VALIDATION_ERROR", meta={"unhandled": True})
        return _err("VALIDATION_ERROR", "Request could not be processed due to an unexpected condition.")
